    public void SENTRYMOBILE_2045_A_FTFP10_PS1_MP1_PMT_LPRM_e_MTIV_ES1_VPSH_VICAE_VIAC(Map<String, String> objDictionary, String strLicensePlateNumber)throws Exception
   	{
    	objDictionary.put("strMobileDeviceType", "ANDROID");
	  	CommonANDROID clsCommonMobile = new CommonANDROID();
	  	Meter clsMeter = new Meter();
	  	CommonWeb clsCommonWeb = new CommonWeb();
	  	clsCommonMobile.SENTRYMOBILE_AddReportVariables(objDictionary);
      	Reporter.log("***************TestCase Description***************************************");
      	Reporter.log("FTFP10: Free Time First Payment 0                                         ");
		Reporter.log("PS1: Park Spot 1                                                          ");
		Reporter.log("MP1: Mobile Payment Spot 1                                                ");
		Reporter.log("PMT: Purchase Max Time                                                    ");
		Reporter.log("LPRM_e_MTIV: LastPaymentRemainingMinutes(60) = MeterTimeIncrementValue(60)");
  		Reporter.log("ES1: Exit Spot1                                                           ");
  		Reporter.log("NTPS: Navigate To Parking Session                                         ");
  		Reporter.log("VPSH: Validate Parking Session History                                    ");
  		Reporter.log("VICAE: Validate Image Count After Exit                                    ");
  		Reporter.log("VIAC: Validate Images Appear Correctly                                    ");
  		Reporter.log("**************************************************************************");
  		//Dictionary Variables
  		String strHost = objDictionary.get("strHost");
		String strSpotNumber = objDictionary.get("strSpotNumber");
  		//Test Case Variables
		String strMaximumDuration = "250";
		String strCoinTimePuchaseLimit = "250";
		String strFreeTimeFirstPayment = "10";objDictionary.put("strFreeTimeFirstPayment", strFreeTimeFirstPayment);
  		String strMeterIncrementTime = "60";objDictionary.put("strMeterIncrementTime", strMeterIncrementTime);
		String strInitialGracePeriod = "1";
		String strViolationGracePeriod = "1";
		String strHandicapInitialGracePeriod = "5";
		String strHandicapViolationGrace = "1";
		String strNoParkingGrace = "1";
		String strParkingShortSessionSec = "15";
		String strSetImageSendBeforeViolation = "45";
		String strUnlockValue = "On";
  		String strUnlockTime = "1";
  		String strUnlockMax = "1";
  		//ExitSpotAndSetMeterRateBlocks
  		clsCommonWeb.SENTRYLINK_ExitSpotSetMeterRateBlocksOpenMeterInBrowse(objDictionary,  strMaximumDuration, strCoinTimePuchaseLimit, strFreeTimeFirstPayment, strMeterIncrementTime, strInitialGracePeriod, strViolationGracePeriod, strHandicapInitialGracePeriod, strHandicapViolationGrace, strNoParkingGrace,strSetImageSendBeforeViolation,strParkingShortSessionSec, strUnlockValue, strUnlockTime, strUnlockMax,"Local");
  		//ParkTP: Park Then Pay
      	AndroidDriver androiddriver = clsCommonMobile.SetMobileDriver(objDictionary, "SentryMobile","True","Parker");
      	clsCommonMobile.SENTRYMOBILE_Open(objDictionary, androiddriver);
      	clsCommonMobile.SENTRYMOBILE_LoginOrRegisterWithRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver, "parker",strLicensePlateNumber, "Enroll later");
      	Reporter.log("strLicensePlateNumber: "+strLicensePlateNumber);
      	//Navigate to Meter Payment
  		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
  		clsCommonMobile.SENTRYMOBILE_PopulateOrValidateMeterPaymentMunicipality(objDictionary, androiddriver, "True");
  		clsCommonMobile.SENTRYMOBILE_PopulateMeterSpotAndLicensePlate(objDictionary, androiddriver, strLicensePlateNumber, "Alabama");
  		//PS1 Park Spot 1
  		clsMeter.METER_ParkSpot(objDictionary,"1","Local");
  		//PMT: Purchase Max Time
  		Double dblCoinIncrementValue = (Double.parseDouble(strMaximumDuration)-Integer.parseInt(strFreeTimeFirstPayment))/Double.parseDouble(strMeterIncrementTime);
      	int intCoinIncrementValue = (int)Math.ceil(dblCoinIncrementValue);
      	int intAddCounter = 0;
      	String strTotalFee = "";
      	while (intAddCounter < intCoinIncrementValue)
  		{
      		//New
      		clsMeter.StoreDumpStackValuesInDictionary(objDictionary, null, strSpotNumber, "Local", "Before");
      		String strOriginalValidTimePurchase = objDictionary.get("strValidTimePurchased").replace(".0", "");
      		String strOriginalMaxRemaining = objDictionary.get("strMaxRemaining");
      		String strMeterFreeValue = objDictionary.get("strMeterFreeValue");
			clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Meter Payment", "{TextExists} Meter Payment~Meter Amount", 60);
  			strTotalFee = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Meter Amount", 1, "strTotalFee");
  			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Purchase Parking", 1);
  			if (intAddCounter == 0){clsCommonMobile.SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee(objDictionary, androiddriver, strTotalFee,"1");}
  			else{clsCommonMobile.SENTRYMOBILE_ValidateSubsequentPaymentDialogAndReturnParkingFee(objDictionary, androiddriver, strTotalFee);}
  			clsCommonMobile.CLICK_MeterPayment_YesPurchase(objDictionary, androiddriver, strLicensePlateNumber);
  			//Click DropDownArrow
  			int intPurchaseTime = 0;
  			if(intAddCounter == 0)
  			{
  				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);
  				//try {Thread.sleep(1500);}catch (Exception e) {}
  				intPurchaseTime = Integer.parseInt(strMeterIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment);
  			}
  			else
  			{intPurchaseTime = Integer.parseInt(strMeterIncrementTime);}
  			 //New  //Not Sure How To Handle Free To Rate
  			String strCurrentValidTimePurchase = clsMeter.GetMeterValidTimePurchased(objDictionary,null,strSpotNumber,"Local","After");
  			if(strMeterFreeValue.equals("False"))
  			{
	  			double dblExpectedMeterValue;
	  			if(Double.parseDouble(strOriginalValidTimePurchase) == 0)
	  			{
	  				dblExpectedMeterValue = Double.parseDouble(strOriginalValidTimePurchase) + Double.parseDouble(strMeterIncrementTime) + Double.parseDouble(strFreeTimeFirstPayment);
	  			}
	  			else{dblExpectedMeterValue = Double.parseDouble(strOriginalValidTimePurchase) + Double.parseDouble(strMeterIncrementTime);}
	  			if(dblExpectedMeterValue == Double.parseDouble(strCurrentValidTimePurchase))
	  			{
	  				Reporter.log("Meter Time decremented correctly after coin payment-("+dblExpectedMeterValue+")");
	  			}
	  			else
	  			{
	  				clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,null,"Meter Time did not decremented correctly after coin payment-expected ("+dblExpectedMeterValue+")-actual ("+strCurrentValidTimePurchase+")");
	  			}
  			}
  			//Purchase Parking Dialog Handler
  			clsCommonMobile.SENTRYMOBILE_PurchaseParkingDialogHandler(objDictionary,androiddriver, strLicensePlateNumber);
  			//Validate Receipt
  			try {Thread.sleep(2000);}catch (Exception e) {}
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", strTotalFee);
		    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
			String strPurchaseAt = dateFormat.format(date);
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "Contains", strPurchaseAt);
			try {Thread.sleep(1000);}catch (Exception e) {}
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "Contains", intPurchaseTime+" Minutes");
			intAddCounter++;
			if(intAddCounter < intCoinIncrementValue){clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "Purchase More", 1);}
			try {Thread.sleep(1000);}catch (Exception e) {}
  		}
      	//Store Parking Id
  		HttpConnections clsHttpConnections = new HttpConnections();
  		clsHttpConnections.HTTPCONNECTIONS_StoreParkingId(objDictionary, "Local", "1");
	  	//Validate Rate Purchase Max Time Parking Session Values
  		clsCommonMobile.SENTRYMOBILE_ValidateRatePurchaseMaxTimeParkingSessionValues(objDictionary, androiddriver, strLicensePlateNumber,strMaximumDuration, strFreeTimeFirstPayment);
      	androiddriver.quit();
      	//ShortSessionWaitExitSpot
      	clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null,"1","Local");
      	//ValidateParkingSessionHistoryAndImages
      	Android_ParkingSessions clsAndriodParkingSessions = new Android_ParkingSessions();
      	clsAndriodParkingSessions.SENTRYLINK_ValidateParkingSessionHistoryAndImages_2045_A_FTFP10_PS1_MP1_PMT_LPRM_e_MTIV_ES1(objDictionary);
      	clsMeter.METER_SetMeterEndTime(objDictionary);
   	}
