    //ANDROID DRIVER
	public AndroidDriver SetMobileDriver(Map<String, String> objDictionary, String strApplication, String strGPSEnabled, String strRole) {
	    String strStopAndStartAppiumServer = objDictionary.get("strStopAndStartAppiumServer");
	    String strAndroidUdid = objDictionary.getOrDefault("strAndroidUdid", "");
	    String strDeviceAppiumPort = objDictionary.getOrDefault("strDeviceAppiumPort", "6666");
	    String strAVDName = objDictionary.getOrDefault("strAVDName", "");
	    String strEnableUiautomator2 = objDictionary.getOrDefault("strEnableUiautomator2", "False");
	    objDictionary.put("strGPSEnabled", strGPSEnabled);
	    objDictionary.put("strApplication", strApplication);
	    AndroidDriver androidDriver = null;

	    // Set device phone number based on UDID
	    switch (strAndroidUdid) {
	        case "R5CW42VHVZY":
	            objDictionary.put("strDevicePhone", "16124777378");
	            break;
	        case "VS986a4741414":
	            objDictionary.put("strDevicePhone", "16513413525");
	            break;
	        case "LGTP2605408c68a":
	            objDictionary.put("strDevicePhone", "195220054");
	            break;
	    }

	    // Stop and start Appium server if required
	    if ("True".equalsIgnoreCase(strStopAndStartAppiumServer)) {
	        if (strAndroidUdid.isEmpty()) {
	            try { Runtime.getRuntime().exec("killall qemu-system-x86_64"); } catch (Exception e) {}
	            try { Runtime.getRuntime().exec("killall qemu-system-i386"); } catch (Exception e) {}
	            try { Thread.sleep(15000); } catch (Exception e) {}
	        }
	        stopServer(objDictionary);
	        try { Thread.sleep(4000); } catch (Exception e) {}
	        startServer(objDictionary);
	        try { Thread.sleep(4000); } catch (Exception e) {}
	    }

	    // Initialize UiAutomator2Options
	    UiAutomator2Options options = new UiAutomator2Options();
	    options.setPlatformName("Android");
	    options.setNewCommandTimeout(Duration.ofMinutes(6));
	    options.setCapability("appium:unicodeKeyboard", true);
	    options.setCapability("appium:clearSystemFiles", true);

	    // ==================== INSPECTION MODE ====================
	    String strInspectionMode = objDictionary.getOrDefault("strInspectionMode", "False");

	    if ("True".equalsIgnoreCase(strInspectionMode)) {
	        // Attach to already running app - no reset
	        options.setNoReset(true);
	        options.setFullReset(false);
	        options.setCapability("appium:dontStopAppOnReset", true);
	        options.setCapability("appium:autoLaunch", false);
	        options.setCapability("appium:shouldTerminateApp", false);
	        options.setCapability("appium:forceAppLaunch", false);

	        System.out.println("=== INSPECTION MODE ENABLED - Attaching to running app ===");
	        Reporter.log("=== INSPECTION MODE ENABLED - Attaching to running app ===");
	    } else {
	        // Normal test mode
	        String strInstallApp = objDictionary.getOrDefault("strInstallApp", "True");
	        if ("True".equalsIgnoreCase(strInstallApp)) {
	            options.setFullReset(true);
	        } else {
	            options.setNoReset(true);
	            options.setFullReset(false);
	        }
	    }
	    // =======================================================

	    String strUserDir = System.getProperty("user.dir");
	    options.setChromedriverExecutable(strUserDir + "/Lib/Android_Chromedriver/chromedriver");

	    String strMobileAPK = objDictionary.get("strMobileAPK");
	    if ("True".equalsIgnoreCase(strEnableUiautomator2)) {
	        int systemPort = Integer.parseInt(strDeviceAppiumPort);
	        options.setAutomationName("UiAutomator2")
	               .setSystemPort(systemPort);
	    } 

	    // Set device or emulator details
	    if (strAndroidUdid.isEmpty()) {
	        options.setAvd(strAVDName.replace(" ", "_"))
	               .setDeviceName(strAVDName);
	    } else if (strMobileAPK != null && strMobileAPK.contains("Flutter")) {
	        options.setDeviceName("DeviceName")
	               .setUdid(strAndroidUdid);
	    }

	    // Set APK path and orientation based on application
	    String strAPKpath = null;
	    if ("SentryMobile".equals(strApplication)) {
	        options.setOrientation(ScreenOrientation.PORTRAIT);
	        strAPKpath = strUserDir + "/APK/" + strMobileAPK;
	        Reporter.log("strAPKpath: " + strAPKpath);
	        System.out.println(strAPKpath);
	        options.setApp(strAPKpath);
	    } else if ("PEO".equals(strApplication)) {
	        options.setOrientation(ScreenOrientation.PORTRAIT);
	        String strPEOAPK = objDictionary.get("strPEOAPK");
	        strAPKpath = strUserDir + "/APK/" + strPEOAPK;
	        System.out.println(strAPKpath);
	        options.setApp(strAPKpath);
	    } else {
	        String strErrorMsg = "The Application (" + strApplication + ") has not been added";
	        Reporter.log("<font color='red'>" + strErrorMsg + "</font>");
	        Assert.fail(strErrorMsg);
	    }

	    // Initialize driver
	    try {
	        androidDriver = new AndroidDriver(new URL("http://127.0.0.1:" + strDeviceAppiumPort), options);
	        try { Thread.sleep(2000); } catch (Exception e) {}
	        
	        SENTRYMOBILE_SETGPSSettings(objDictionary, androidDriver, strGPSEnabled);
	        Reporter.log("Sentry Mobile was loaded correctly on Android Device");

	        if (!"PEO".equals(strApplication)) {
	            try {
	                SENTRYMOBILE_CheckUserAccountBalanceAddFundsIfNeeded(objDictionary, strRole);
	            } catch (Exception e) {}
	        }
	    } catch (Exception e) {
	        // ... your existing error handling remains unchanged ...
	        String strErrorMsg = "Could not initialize Android driver: " + e.getMessage();
	        // (rest of your catch block stays the same)
	    }

	    // Check battery life
	    String strDeviceName = androidDriver.getCapabilities().getCapability("deviceName").toString();
	    int intBatteryLife = METER_ADB_GetBatteryLife(strDeviceName, "cat /sys/class/power_supply/battery/capacity");
	    if (intBatteryLife < 4) {
	        String strErrorMsg = "The Battery Power on device (" + intBatteryLife + ") is under 4%";
	        Reporter.log("<font color='red'>" + strErrorMsg + "</font>");
	        Assert.fail(strErrorMsg);
	    }

	    androidDriver.unlockDevice();
	    return androidDriver;
	}
	
	
	// === HELPER METHODS ===
	private void execCmd(String cmd) {
	    try {
	        Runtime.getRuntime().exec(cmd);
	    } catch (Exception ignored) {}
	}
	private void sleep(long millis) {
	    try {
	        Thread.sleep(millis);
	    } catch (Exception ignored) {}
	}

	
    public int METER_ADB_GetBatteryLife(String deviceId,String command)
    {
        Process proc = null;
        String commandString;
        String strAutomationUser = System.getProperty("user.name");
        if(deviceId != null) {commandString = String.format("%s", "/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s " + deviceId + " shell " + command);}
        else{commandString = String.format("%s", "adb shell " + command);}
        String line = "";
        try
        {
        	proc = Runtime.getRuntime().exec(commandString);
        	BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getInputStream()));
        	while ((line = reader.readLine()) != null) {break;}
        }
        catch (IOException e) {System.out.println(e);}
        if(line != null)
        {
        	return Integer.parseInt(line);
        }
        else
        {
        	return 5;
        }
    }
    public int METER_ADB_GetAndriodVersion(String deviceId,String command)
    {
        Process proc = null;
        String commandString;
        String strAutomationUser = System.getProperty("user.name");
        if(deviceId != null) {commandString = String.format("%s", "/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s " + deviceId + " shell " + command);}
        else{commandString = String.format("%s", "adb shell " + command);}
        String line = "";
        try
        {
        	proc = Runtime.getRuntime().exec(commandString);
        	BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getInputStream()));
        	while ((line = reader.readLine()) != null) {break;}
        }
        catch (IOException e) {System.out.println(e);}
        if(line != null)
        {
        	return Integer.parseInt(line);
        }
        else
        {
        	return 5;
        }
    }

    public void SENTRYMOBILE_SETGPSSettings(Map<String, String> objDictionary,AndroidDriver androiddriver, String strGPSEnabled)
    {
    	String strLocation = objDictionary.get("strLocation");
	    String strAutomationUser = System.getProperty("user.name");
		String strDeviceName = (String)androiddriver.getCapabilities().getCapability("deviceName");
		System.out.println(strGPSEnabled);
		System.out.println(strAutomationUser);
		int intAndroidVersion = METER_ADB_GetAndriodVersion(strDeviceName,"getprop ro.build.version.release");
		if(strGPSEnabled.equals("True"))
		{
			if (intAndroidVersion >= 13)
			{
				//Disable GPS
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_providers_allowed +network");}
				catch(Exception e){}
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_mode 3");}
				catch(Exception e){}
			}
			else
			{
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s  "+strDeviceName+"shell settings put secure location_providers_allowed +network");}
				catch(Exception e){}
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s  "+strDeviceName+" shell settings put secure location_providers_allowed +gps");}
				catch(Exception e){}
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s  "+strDeviceName+" emu geo fix "+strLocation);}
				catch(Exception e){}
			}
		}
		else
		{
			if (intAndroidVersion >= 13)
			{
				//Disable GPS
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_providers_allowed -network");}
				catch(Exception e){}
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_mode 0");}
				catch(Exception e){}
			}
			else
			{
				//Disable GPS
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_providers_allowed -network");}
				catch(Exception e){}
				//try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_mode 0");}
				try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb  -s  "+strDeviceName+" shell settings put secure location_providers_allowed -gps");}
				catch(Exception e){}
			}
		}
    }



    public AndroidDriver SetMobileDriverWithFullResetOptiond(Map<String, String> objDictionary, String strApplication, String strFullReset)
    {
	    	try{Runtime.getRuntime().exec("killall Simulator");}catch(Exception e){}
	    	try{Runtime.getRuntime().exec("killall qemu-system-x86_64");}catch(Exception e){}
	    	try{Runtime.getRuntime().exec("killall qemu-system-i386");}catch(Exception e){}
	    	try {Thread.sleep(5000);}catch (Exception e) {}
	    	String strStopAndStartAppiumServer = objDictionary.get("strStopAndStartAppiumServer");
	    	if (strStopAndStartAppiumServer == "True")
	    	{
	    		stopServer(objDictionary);try {Thread.sleep(2000);}catch (Exception e) {}
	    		startServer(objDictionary);try {Thread.sleep(2000);}catch (Exception e) {}
	    	}
	    	String strAppiumPort = objDictionary.get("strAppiumPort");
	    	String strAVDName = objDictionary.get("strAVDName");
	    	String strLocation = objDictionary.get("strLocation");
	    	String strAndroidUdid = objDictionary.get("strAndroidUdid");
	    	String strAPKpath = null;
	    	DesiredCapabilities capabilities = new DesiredCapabilities();
	    	capabilities.setCapability("unicodeKeyboard", true);
	    	capabilities.setCapability("platformName", "ANDROID");
	    	capabilities.setCapability("newCommandTimeout", 60 * 5);
	    	//Added to for this error: Not cleaning generated files. Add `clearSystemFiles` capability if wanted.
	    	capabilities.setCapability("clearSystemFiles",true);
	    	String strUserDir = System.getProperty("user.dir");
	    	if(strFullReset.equals("True"))
	    	{
	    		capabilities.setCapability("fullReset", true);
	    	}
	    	String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		objDictionary.remove("strApplication"); objDictionary.put("strApplication",strApplication);
		if(strAndroidUdid == null)
		{
			//Use Emulator
			capabilities.setCapability("avd", strAVDName.replace(" ","_"));
			capabilities.setCapability("deviceName",strAVDName);
		}
		else if(strAndroidUdid.equals(""))
		{
			//Use Emulator
			capabilities.setCapability("avd", strAVDName.replace(" ","_"));
			capabilities.setCapability("deviceName",strAVDName);
		}
		else
		{
			//User Real Device
			capabilities.setCapability("deviceName", "DeviceName");
			capabilities.setCapability("udid",strAndroidUdid);
		}
		if(strApplication.equals("SentryMobile"))
		{
			capabilities.setCapability("orientation","PORTRAIT");
			String strMobileAPK = objDictionary.get("strMobileAPK");
			strAPKpath=strUserDir+"/APK/"+strMobileAPK;
			File app=new File(strAPKpath);
			capabilities.setCapability("app", app.getAbsolutePath());
		}
		else if(strApplication.equals("PEO"))
		{
			String strPEOAPK = objDictionary.get("strPEOAPK");
			strAPKpath=strUserDir+"/APK/"+strPEOAPK;
			File app=new File(strAPKpath);capabilities.setCapability("app", app.getAbsolutePath());
		}
		else
		{
			String strErrorMsg = "The Application ("+strApplication+") has not been added-"+strMethondName+"";
    		Reporter.log("<font color='red'>"+strErrorMsg+"</font>");Assert.fail(strErrorMsg);
		}
		try
		{
			AndroidDriver androiddriver  = null;
			androiddriver  = new AndroidDriver(new URL("http://127.0.0.1:"+strAppiumPort+"/wd/hub"), capabilities);
			String strAutomationUser = System.getProperty("user.name");
			String strDeviceName = (String)androiddriver.getCapabilities().getCapability("deviceName");
			try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s  "+strDeviceName+" emu geo fix "+strLocation);}
			catch(Exception e){}
			return androiddriver;
		}
		catch (Exception e)
		{
			String strErrorMsg = "";
			if(e.toString().contains("ANDROID_HOME"))
			{strErrorMsg = "Could not find a connected Android device.-ANDROID_HOME Does Not Exist";}
			else
			{strErrorMsg = "Could not find a connected Android device."+e;}
			Reporter.log("<font color='red'>"+strErrorMsg+"</font>");Assert.fail(strErrorMsg);
			return null;
		}
    }
