    public void PEO_ClearLegacySessions(Map<String, String> objDictionary)
    {
    	CommonANDROID clsCommonMobile = new CommonANDROID();
    	//Clear Legacy Sessions
		AndroidDriver androiddriver = clsCommonMobile.SetMobileDriver(objDictionary, "PEO","True","Parker");
		clsCommonMobile.PEO_Login(objDictionary, androiddriver);
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Violations", "Menu", 1);
		clsCommonMobile.ClickLink(objDictionary, androiddriver, "Violations", "Legacy Sessions", 1);
		String strTimeoutFlag = "True";
		do
		{
			String strConditionalValue = clsCommonMobile.ConditionalStepButton(objDictionary, androiddriver, "Legacy Sessions", "Clear", 1, "Exists", "");
			if(strConditionalValue.equals("True"))
			{
				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Legacy Sessions", "Clear",1);
				try {Thread.sleep(2000);}catch (Exception e) {}
				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Legacy Sessions", "Confirm",1);
			}
			else {strTimeoutFlag= "False";}

		}while (strTimeoutFlag.equals("True"));
		androiddriver.quit();
    }


    public void PEO_ValidateInProgressViolationsExists(Map<String, String> objDictionary, AndroidDriver androiddriver, String strViolationId)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		String strInProgressViolationExists = "False";
		int intTextIndex = 1;
		//Need to Get Number of In Progress Violation on Screen.
		do
        {
			objDictionary.put("intTextIndex",Integer.toString(intTextIndex));
			String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "In Progress Violations", "Violation No", intTextIndex, "Exists", "");
			if(strConditional.equals("True"))
			{
				String strInProgressViolationId = clsCommonMobile.StoreText(objDictionary, androiddriver, "In Progress Violations", "Violation No", intTextIndex, "strClaimViolationId");
				//System.out.println(strClaimedViolationId);
				if(strInProgressViolationId.equals(strViolationId))
				{
					Reporter.log("The Violation ("+strViolationId+") appeared correctly on the In Progress Violation Screen");
					return;
				}
				intTextIndex++;
			}
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Violation ("+strViolationId+") did not exist on the In Process Violations Screen");}
			if(intTextIndex > 3)
			{
				clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Violation ("+strViolationId+") did not exist on the In Process Violations Screen");
			}
        }while (strInProgressViolationExists == "False");
	}
