	public void PEO_ClaimViolation(Map<String, String> objDictionary, AndroidDriver androiddriver, String strViolationId)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Click Refresh to Fetch Violations
		//clsCommonMobile.GlobalWait(objDictionary, androiddriver, "New Violations", "{ButtonExists} New Violations~Refresh", 40);
		//try {Thread.sleep(3500);}catch (Exception e) {}//Need better Sync
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "New Violations", "Refresh", 1);
		//Need to get The Claim button index
		String strClaimeExists = "False";
		int intTextIndex = 1;
		//Need to Get Number of Violation on Screen.
		do
        {
			//try {Thread.sleep(5000);}catch (Exception e) {}//Need better Sync
			objDictionary.put("intTextIndex",Integer.toString(intTextIndex));
			clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Violations", "{TextExists} Violations~Violation No", 45);
			String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Violations", "Violation No", intTextIndex, "Exists", "");
			if(strConditional.equals("True"))
			{
				String strClaimedViolationId = clsCommonMobile.StoreText(objDictionary, androiddriver, "Violations", "Violation No", intTextIndex, "strClaimViolationId");
				System.out.println(strClaimedViolationId);
				if(strClaimedViolationId.equals(strViolationId))
				{
					ClickButton(objDictionary, androiddriver, "Violations", "Claim",intTextIndex);
					strClaimeExists = "True";
				}
				intTextIndex++;
			}
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Violation ("+strViolationId+") did not exist on the Violations Screen");}
			if(intTextIndex > 4)
			{
				clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Violation ("+strViolationId+") did not exist on the Violations Screen");
			}
        }while (strClaimeExists == "False");
		PEO_ValidateViolationInformation(objDictionary, androiddriver);
	}
	public void PEO_CreateManualViolation(Map<String, String> objDictionary, AndroidDriver androiddriver, String strLicensePlate, String strLicensePlateState, String strRegistrationExpYear, String strRegistrationExpMonth, String strVehicleMake, String strViolationReason, String strSpotId, String strRemarks)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonMobile.GlobalWait(objDictionary, androiddriver, "Violations", "{ButtonExists} Violations~Menu", 30);
		ClickButton(objDictionary, androiddriver, "Violations", "Menu", 1);
		ClickLink(objDictionary, androiddriver, "Violations", "Create New Violation", 1);
		PEO_PopulateVehicleDetails(objDictionary, androiddriver,strLicensePlate, strLicensePlateState, strRegistrationExpYear, strRegistrationExpMonth, strVehicleMake);
		PEO_PopulateViolationDetails(objDictionary, androiddriver, strViolationReason, strSpotId, strRemarks);
		try {Thread.sleep(1500);}catch (Exception e) {}
		WebElement objTicketFrame = androiddriver.findElement(By.xpath(".//android.widget.ScrollView[1]"));
		ElementSwipe  clsElementSwipe  = new ElementSwipe();
		String strNumberOfViolationImages = objDictionary.get("strNumberOfViolationImages");if(strNumberOfViolationImages == null) {strNumberOfViolationImages = "0";}
		if(!strNumberOfViolationImages.equals("0"))
		{
			int intNumberOfViolationImages = Integer.parseInt(strNumberOfViolationImages);
			for(int intViolationCount = 1; intViolationCount<= intNumberOfViolationImages; intViolationCount++)
			{
				//Add 1st Violation Picture
				if(intViolationCount == 1)
				{clsCommonMobile.ClickButton(objDictionary, androiddriver, "Issue ticket", "Violation Picture",1);}
				else
				{clsCommonMobile.ClickButton(objDictionary, androiddriver, "Issue ticket", "Violation Picture "+intViolationCount,1);}
				try {Thread.sleep(1500);}catch (Exception e) {}
				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Issue ticket", "Picture Button",1);
				try {Thread.sleep(3500);}catch (Exception e) {}
				clsCommonMobile.ClickLink(objDictionary, androiddriver, "Issue ticket", "OK", 1);
				try {Thread.sleep(1500);}catch (Exception e) {}
				objTicketFrame = androiddriver.findElement(By.xpath(".//android.widget.ScrollView[1]"));
				clsElementSwipe.Swipe(androiddriver,objTicketFrame,"SWIPE_UP");
				try {Thread.sleep(1000);}catch (Exception e) {}
				if(intViolationCount > 1)
				{
					int intSwipeNumber = intViolationCount;
					WebElement objPictureFrame = androiddriver.findElement(By.id("com.mpspark.mobileOfficer:id/imgViolationPicture"+intSwipeNumber));
					clsElementSwipe.Swipe(androiddriver,objPictureFrame,"SWIPE_LEFT");
					clsElementSwipe.Swipe(androiddriver,objPictureFrame,"SWIPE_LEFT");
					try {Thread.sleep(1000);}catch (Exception e) {}
				}
			}
		}
		ClickButton(objDictionary, androiddriver, "New Violation", "Generate Ticket", 1);
	}
