	public void PEO_ValidateTicketValues(Map<String, String> objDictionary, AndroidDriver androiddriver, String strTicketAmountDue,String strSpotNumber)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		clsCommonMobile.GlobalWait(objDictionary, androiddriver, "Ticket", "{TextFieldExists} Ticket~Plate", 45);
		clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "Plate", 1, "Contains", "~strLicensePlate~");
		String strRegistrationExpMonth = objDictionary.get("strRegistrationExpMonth");
		String strRegistrationExpYear = objDictionary.get("strRegistrationExpYear");
		String  strRegistrationType = objDictionary.get("strRegistrationType");
		String  strBodyType = objDictionary.get("strBodyType");
		String  strVehicleMake = objDictionary.get("strVehicleMake");
		String strDeviceId = objDictionary.get("strDeviceId");
		String strStatuteCode = objDictionary.get("strStatuteCode");
		String[] arrMeterSpots = strDeviceId.split("-");
		String strMeterSpotName = "";
		if(strSpotNumber.equals("1")){strMeterSpotName = arrMeterSpots[0];}else{strMeterSpotName = arrMeterSpots[1];}
		//Double Sided
		if(strRegistrationExpMonth != null||strRegistrationExpYear != null)
		{
			clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "REG.EXP.DATE", 1, "Contains", strRegistrationExpMonth+"/"+strRegistrationExpYear);
		}
		clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "REG TYPE", 1, "Contains", strRegistrationType);
		clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "BODY TYPE", 1, "Contains", strBodyType);
		//Vehicle Make
		if(strVehicleMake != null)
		{clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "VEHICLE MAKE", 1, "Contains", strVehicleMake);}
		else
		{clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "VEHICLE MAKE", 1, "Value", "");}
		//Meter
		clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Ticket", "Meter", 1, "Contains", strMeterSpotName);
		//Single Sided
//		clsCommonMobile.VerificationPointCheckbox(objDictionary, androiddriver, "Ticket", "", "Other", 1, "Value", "Checked");
//		clsCommonMobile.VerificationPointCheckbox(objDictionary, androiddriver, "Ticket", "Reg.Type", strRegistrationType, 1, "Value", "Checked");
//		clsCommonMobile.VerificationPointCheckbox(objDictionary, androiddriver, "Ticket", "Body Type","~strBodyType~", 1, "Value", "Checked");
//		Emulator-clsCommonMobile.VerificationPointCheckbox(objDictionary, androiddriver, "Ticket", "", "In Front Of", 1, "Value", "Checked");
		WebElement objTicketFrame = androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.widget.ScrollView[1]"));
		String strViolationReason = ConvertValues(objDictionary, androiddriver, "~strViolationReason~");
		String strConditionalValue = ConditionalStepCheckbox(objDictionary, androiddriver, "Ticket", "", strViolationReason+"			"+strStatuteCode, 1, "Exists", "");
		if(strConditionalValue.equals("False"))
		{
			ElementSwipe  clsElementSwipe  = new ElementSwipe();
			clsElementSwipe.Swipe(androiddriver,objTicketFrame,"SWIPE_UP");
			try {Thread.sleep(1000);}catch (Exception e) {}
		}
//		if(strStatuteCode.equals("250-50-B")){strViolationReason = "Pkd. Expired Meter";}
//		clsCommonMobile.VerificationPointCheckbox(objDictionary, androiddriver, "Ticket", "", strViolationReason+"			"+strStatuteCode, 1, "Value", "Checked");
	}
