	public void PEO_CreateManualSessionForDescriptionAndStatuteCodeValidation(Map<String, String> objDictionary, AndroidDriver androiddriver, String strViolationDescription, String strTicketAmountDue, String strSpotNumber)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Dictionary Variables
		String strDeviceId = objDictionary.get("strDeviceId");
		String[] arrMeterSpots = strDeviceId.split("-");
		String strMeterSpotName = "";
		if(strSpotNumber.equals("1")){strMeterSpotName = arrMeterSpots[0];}
		else
		{
			if(arrMeterSpots.length < 2){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"This Test Requires dual meters-"+strMethondName);}
			else{strMeterSpotName = arrMeterSpots[1];}
		}
		if (!strSpotNumber.equals("1") && strMeterSpotName.equals("")) {strMeterSpotName = strDeviceId;}
		String strMunicipality = objDictionary.get("strMunicipality");
		if(strMunicipality.equals("Excelsior, MN")) {strViolationDescription = "Blocking Driveway";}
		PEO_CreateManualSession(objDictionary, androiddriver, "ARGOFY", "Alabama", "2024", "04", "AMC", strViolationDescription, strMeterSpotName, "");
	}
