	public void PEO_ValidateViolationRemoved(Map<String, String> objDictionary, AndroidDriver androiddriver, String strViolationId)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		int intTextIndex = 1;
		String strCondition = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Violations", "Violation No", intTextIndex, "Exists", "");
		if(strCondition.equals("True"))
		{
			String strValidated = "True";
			do
	        {
				String strClaimedViolationId = clsCommonMobile.StoreText(objDictionary, androiddriver, "Violations", "Violation No", intTextIndex, "strClaimViolationId");
				if(strClaimedViolationId.equals(strViolationId))
				{
					clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Violation ("+strViolationId+") was not removed from the violation list");
				}
				intTextIndex++;
				strValidated = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Violations", "Violation No", intTextIndex, "Exists", "");
			}while (strValidated == "True");
			Reporter.log("The Violation ("+strViolationId+") was removed correctly");
		}
		else
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Violations", "No Violations to show", 1, "Exists", "");}
	}
