	public void SENTRYMOBILE_CheckUserAccountBalanceAddFundsIfNeeded(Map<String, String> objDictionary, String strRole) throws Exception
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		String strCurrentAccountBalance = "";
		try{strCurrentAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary,strRole);}
		catch (Exception e) {}
		//Add Money If Balance is less than $5.00
		double dblStringUserAccountBalance = Double.parseDouble(strCurrentAccountBalance) * .01;
		Reporter.log("The user account balance was ("+dblStringUserAccountBalance+")");
		objDictionary.put("strCurrentAccountBalance", String.valueOf(dblStringUserAccountBalance));
		String strEnvironment = objDictionary.get("strEnvironment");
		if(!strEnvironment.equals("PROD"))
		{
			if(dblStringUserAccountBalance < 25.00)
			{
				//Add Money Through API
				clsHttpConnections.POST_JsonDepositFunds(objDictionary,strRole);
				try{strCurrentAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary,strRole);}
				catch (Exception e) {}
				//Add Money If Balance is less than $5.00
				dblStringUserAccountBalance = Double.parseDouble(strCurrentAccountBalance) * .01;
				Reporter.log("The user account balance was ("+dblStringUserAccountBalance+")");
				objDictionary.put("strCurrentAccountBalance", String.valueOf(dblStringUserAccountBalance));
			}
		}
	}
	public void SENTRYMOBILE_AddMoneyToAccountIfNeeded(Map<String, String> objDictionary, String strRole)throws IOException
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		//Function Variables
		String strCurrentAccountBalance = "";
		strCurrentAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary,strRole);
		double dblCurrentAccountBalance = Double.parseDouble(strCurrentAccountBalance)/100;
		//Add Money to Account if Balance is less than 5.00 add money
		if(5.00 > dblCurrentAccountBalance)
		{
			//Add Money Through API
			clsHttpConnections.POST_JsonDepositFunds(objDictionary, strRole);
		}
	}
