	public void SENTRYMOBILE_GoogleMapClickMeterTag(Map<String, String> objDictionary,AndroidDriver androiddriver)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMeterSpotName = objDictionary.get("strMeterSpotName");
		//Wait for map to load
		SENTRYMOBILE_SETGPSSettings(objDictionary,androiddriver, "True");
		try {Thread.sleep(3000);}catch (Exception e) {}
		clsCommonMobile.GlobalWait(objDictionary, androiddriver, "Nearby Parking", "{ButtonExists} Nearby Parking~Center Map", 30);
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Nearby Parking", "Center Map", 1);
		try {Thread.sleep(2000);}catch (Exception e) {}
		try
		{
			List<WebElement> objGoogleMap = androiddriver.findElements(By.xpath("//*[contains(@content-desc,'Google Map')]"));
			List<WebElement> objGoogleMarkers = objGoogleMap.get(0).findElements(By.className("android.view.View"));
			for (WebElement objGoogleMarker : objGoogleMarkers)
			{
				System.out.println(objGoogleMarker.getAttribute("name"));
				if(objGoogleMarker.getAttribute("name").contains(strMeterSpotName))
				{
					System.out.println(objGoogleMarker.getAttribute("name"));
					objGoogleMarker.click();
					Reporter.log("The Meter (" + strMeterSpotName + ") on the Google Map was clicked successfully");
					return;
				}
			}
			clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Meter ("+strMeterSpotName+") did not exist on the Google Map-"+strMethondName);
		}
		catch (Exception e)
		{
			clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Google Map didn't apear-"+strMethondName);
		}
	}
	public void SENTRYMOBILE_GoogleMapZoomToStreetLevel(Map<String, String> objDictionary,AndroidDriver androiddriver, int intNumberOfZooms)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strAndroidUdid = objDictionary.get("strAndroidUdid");if(strAndroidUdid == null) {strAndroidUdid = "";}
		//Set GPS
		SENTRYMOBILE_SETGPSSettings(objDictionary,androiddriver, "True");
		//Click Google Map
		clsCommonMobile.GlobalWait(objDictionary, androiddriver, "Nearby Parking", "{ButtonExists} Nearby Parking~Center Map|{ButtonExists} Nearby Parking~Center Map Xpath", 60);
		try {Thread.sleep(2000);}catch (Exception e) {}
		try
		{
			int y = 0;
			if(strAndroidUdid.equals("")){SENTRYMOBILE_SETGPSSettings(objDictionary,androiddriver, "True");}
			do
			{
				//Click To Center Map
				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Nearby Parking", "Center Map", 1);
				try {Thread.sleep(1000);}catch (Exception e) {}
				//Get the Meter Count
				List<WebElement> objGoogleMap = androiddriver.findElements(By.xpath("//*[contains(@content-desc,'Google Map')]"));
				List<WebElement> objGoogleMarkers = objGoogleMap.get(0).findElements(By.className("android.view.View"));
				objGoogleMarkers.size();
				//If Meter Count is > X
				if(objGoogleMarkers.size() > 40)
				{
					WebElement objCenterMap = androiddriver.findElement(By.id("com.mpspark.consumer.mpsconsumer:id/btnPay"));
					//MobileElement objCenterMap = androiddriver.findElement(By.xpath("//*[contains(@content-desc,'Google Map')]"));
					doubleTap(androiddriver,objCenterMap);
					if(objGoogleMarkers.size() > 100){doubleTap(androiddriver,objCenterMap);}
				}
				else{break;}
			}while (y < intNumberOfZooms);
		}
		catch (Exception e)
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Google Map didn't apear-"+strMethondName);}
		if(strAndroidUdid.equals("")){SENTRYMOBILE_SETGPSSettings(objDictionary,androiddriver, "True");}
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Nearby Parking", "Center Map", 1);
	}
	public String SENTRYMOBILE_CheckIfMeterExistOnGoogleMap(Map<String, String> objDictionary,AndroidDriver androiddriver)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMeterSpotName = objDictionary.get("strMeterSpotName");
		try
		{
			List<WebElement> objGoogleMap = androiddriver.findElements(By.xpath("//*[contains(@content-desc,'Google Map')]"));
			List<WebElement> objGoogleMarkers = objGoogleMap.get(0).findElements(By.className("android.view.View"));
			for (WebElement objGoogleMarker : objGoogleMarkers)
			{
				System.out.println(objGoogleMarker.getAttribute("name"));
				if(objGoogleMarker.getAttribute("name").contains(strMeterSpotName))
				{return "True";}
			}
			clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Meter ("+strMeterSpotName+") did not exist on the Google Map-"+strMethondName);
		}
		catch (Exception e)
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Google Map didn't apear-"+strMethondName);}
		return "False";
	}

	public void doubleTapElement(AndroidDriver androiddriver,WebElement element)
	{
		new TouchAction(androiddriver).press(PointOption.point(element.getLocation().getX(),element.getLocation().getY())).waitAction(WaitOptions.waitOptions(Duration.ofMillis(100))).release().perform();
		new TouchAction(androiddriver).press(PointOption.point(element.getLocation().getX(),element.getLocation().getY())).waitAction(WaitOptions.waitOptions(Duration.ofMillis(100))).release().perform();
    }
	public void doubleTap(AndroidDriver androiddriver,WebElement element)
	{
		org.openqa.selenium.Dimension size = androiddriver.manage().window().getSize();
		// calculate coordinates for vertical swipe
		int startVerticalY = (int) (size.height * 0.8);
		int startVerticalX = (int) (size.width / 2.1);
		new TouchAction(androiddriver).press(PointOption.point(startVerticalX,startVerticalY)).waitAction(WaitOptions.waitOptions(Duration.ofMillis(100))).release().perform();
		new TouchAction(androiddriver).press(PointOption.point(startVerticalX,startVerticalY)).waitAction(WaitOptions.waitOptions(Duration.ofMillis(100))).release().perform();
	}

