	public void SENTRYMOBILE_Open(Map<String, String> objDictionary, AndroidDriver androiddriver)
	{	
		try {Thread.sleep(2000);}catch (Exception e) {}
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Close Push Notification if Open
 		try {androiddriver.findElement(By.xpath("//*[@text='Clear']")).click();}catch(Exception b) {}
		
//		String strAutomationUser = System.getProperty("user.name");
//		try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb shell cmd statusbar collapse");}catch (Exception e) {}
		
		//Pixel Laucher is responding
		try {androiddriver.findElement(By.xpath("//*[@text='Close App']")).click();}catch(Exception b) {}
		//USB Connection
//		try {Thread.sleep(4000);}catch (Exception e) {}
//		try {androiddriver.findElement(By.xpath("//*[@text='Ok']")).click();}
//		catch(Exception b) {}
//		try {Thread.sleep(2000);}catch (Exception e) {}
		try {androiddriver.findElement(By.xpath("//*[@text='Allow']")).click();}catch(Exception b) {}
		try {Thread.sleep(1000);}catch (Exception e) {}
		try {androiddriver.findElement(By.xpath("//*[@text='Ok']")).click();}
		catch(Exception b) {}
		try {androiddriver.findElement(By.xpath("//*[@text='Close']")).click();}
		catch(Exception c) {}
		GlobalWait(objDictionary,androiddriver, "User Agreement", "{PageExists} User Agreement|{PageExists} Login|{ButtonExists} Login~Cancel", 60);
		System.out.println(strActualWaitValue);
		if(strActualWaitValue.equals("User Agreement")){ClickButton(objDictionary, androiddriver, "User Agreement", "Accept",1);}
		if(strActualWaitValue.equals("Cancel"))
		{
			ClickButton(objDictionary, androiddriver, "Login", "Cancel",1);
			ClickButton(objDictionary, androiddriver, "Login", "Remember me",1);
		}
	}	
