	public void SENTRYMOBILE_LoginWithoutCaps(Map<String, String> objDictionary, AndroidDriver androiddriver, String strRole,String strLicensePlateNumber, String strWizardStatus, String strRemainMeStatus)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		HttpConnections  clsHttpConnections = new HttpConnections ();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strUserName = strUniqueId+strMunicipality.replace(" ","").replace(",", "")+strRole+"@gmail.com";
		String strPassword = clsCommonWeb.SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonMobile.PopulateAction(objDictionary, androiddriver, "Login", "Populate Login", "{T} Email Id|{T} Password|{CB} Remember me",strUserName.toLowerCase()+"|"+strPassword.replace(" ", "")+"|Checked");
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Login", "Login",1);
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Login", "{TextExists} Login~Allow Sentry Mobile to access this device's location?", 45);
		try {Thread.sleep(1000);}catch (Exception e) {}
     	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Login", "Allow Sentry Mobile to access this device's location?", 1, "Exists", "");
     	try {Thread.sleep(1000);}catch (Exception e) {}
     	String strAndroidUdid = objDictionary.get("strAndroidUdid");
     	int intAndroidVersion = clsCommonMobile.METER_ADB_GetAndriodVersion(strAndroidUdid,"getprop ro.build.version.release");
	 	if(intAndroidVersion >= 15)
		{
			clsCommonMobile.ClickLink(objDictionary, androiddriver, "Nearby Parking", "While using the app", 1);
		}
	 	else if(intAndroidVersion == 9)
		{
	 		clsCommonMobile.ClickLink(objDictionary, androiddriver, "Nearby Parking", "Allow", 1);
		}
		else
		{
			clsCommonMobile.ClickLink(objDictionary, androiddriver, "Nearby Parking", "Allow only while using the app", 1);
		}
		//clsCommonMobile.SENTRYMOBILE_LoginDialogHandler(objDictionary, androiddriver, strRole);
		String strGPSEnabled = objDictionary.get("strGPSEnabled");
   		if(strGPSEnabled.equals("False"))
   		{
   			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Nearby Parking", "Dialog Message", 1, "Contains", "With GPS disabled, you will only have access to your registered municipality");
   			String strConditional = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Nearby Parking", "CANCEL", 1, "Exists", "");
   			if(strConditional.equals("True"))
   			{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Nearby Parking", "CANCEL", 1);}
   			else
   			{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Nearby Parking", "Cancel", 1);}
   			clsCommonMobile.VerificationPointText(objDictionary,androiddriver, "Account Details", "Do you want to enable biometric authentication for easier login?",1,"Value","Do you want to enable biometric authentication for easier login?");
   			clsCommonMobile.ClickLink(objDictionary, androiddriver, "Account Details", "NOT RIGHT NOW",1);
   	 	}
   		//Concierge Enabled 
   		String strConciergeAdminSetting = clsHttpConnections.GET_GetConciergeAdminSetting(objDictionary, "enabled");
   		if(strConciergeAdminSetting.equals("true"))
   		{
   			//Close Concierge Wizard (Enroll now, Enroll later, never show again)
   		   	String strConciergeState = clsHttpConnections.API_ReturnConciergeState(objDictionary,strRole,strLicensePlateNumber);
			String strEnrolledState = clsHttpConnections.GET_ConciergeEnrolledState(objDictionary, strRole) ; 
			//Current Balance > 10
			String strCurrentParkingAccountBalance = objDictionary.get("strCurrentParkingAccountBalance");
			if(strCurrentParkingAccountBalance == null)
			{
				strCurrentParkingAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary, strRole); 
			}
			Double.parseDouble(strCurrentParkingAccountBalance);
			clsCommonMobile.SENTRYMOBILE_LoginDialogHandler(objDictionary, androiddriver, strRole);
			//No nearby parking spots available. Please retry
			//clsCommonMobile.SENTRYMOBILE_HandleNoNearbyParkingSpotAvailableDialog(objDictionary, androiddriver);
			//The Wizard showed up when strConciergeState = Pending and strEnrolledState = False (A35)
			String strConditionalValue = clsCommonMobile.ConditionalStepButton(objDictionary, androiddriver, "Nearby Parking",strWizardStatus, 1, "Exists", "");
			if(strConditionalValue.equals("True"))
			{
				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Nearby Parking", strWizardStatus, 1);
			}
			
   		}
   		String strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Login", "OK", 1, "Exists", "");
   		if(strCondition.equals("True"))
		{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "OK", 1);}
   		strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Login", "Ok", 1, "Exists", "");
   		if(strCondition.equals("True"))
		{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "Ok", 1);}
	}
