	public void SENTRYMOBILE_HandleNoNearbyParkingSpotAvailableDialog(Map<String, String> objDictionary, AndroidDriver androiddriver)
	{
		try {Thread.sleep(2000);}catch (Exception e) {}
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strExistsCondition = "True";
		int intCounter = 0;
    	do
    	{
    		strExistsCondition = ConditionalStepText(objDictionary,androiddriver, "Login", "Dialog Message", 1, "Exists", "");
    		if(strExistsCondition.equals("True"))
    		{
	    		String strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Nearby Parking", "RETRY", 1, "Exists", "strCondition");
	    		if(strCondition.equals("True"))
	    		{
	    			androiddriver.findElement(By.xpath("//*[@text='RETRY']")).click();
	    			Reporter.log("<font color='orange'>No nearby parking spots available. Please RETRY</font>");
	    		}
	    		else
	    		{
	    			strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Nearby Parking", "Retry", 1, "Exists", "strCondition");
		    		if(strCondition.equals("True"))
		    		{
		    			androiddriver.findElement(By.xpath("//*[@text='Retry']")).click();
		    			Reporter.log("<font color='orange'>No nearby parking spots available. Please retry</font>");
		    		}
		    		else
		    		{strExistsCondition = "False";}
	    		}
    		}
    		intCounter++;
    		if(intCounter > 10){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver, "The Nearby Parking Spot didn't go away after 10 Retries");}
    	}while (strExistsCondition.equals("True"));
	}



	public void SENTRYMOBILE_LoginDialogHandler(Map<String, String> objDictionary, AndroidDriver androiddriver, String strRole)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMunicipality = objDictionary.get("strMunicipality");
		String strCondition = ConditionalStepText(objDictionary,androiddriver, "Login", "Dialog Message", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			String strDialogMessage = clsCommonMobile.StoreText(objDictionary, androiddriver, "Login", "Dialog Message", 1, "strDialogMessage");
			if(strDialogMessage.contains("Invalid Credentials. Please re-enter your email id and password."))
			{
				ClickLink(objDictionary, androiddriver, "Login", "Ok", 1);
				SENTRYMOBILE_RegisterUserRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver,"parker");
				SENTRYMOBILE_LoginAfterRegisteringUserEmailIdWithoutCaps(objDictionary, androiddriver, strRole);
			}
			else if(strDialogMessage.contains("Invalid Credentials."))
			{

				strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Login", "Retry", 1, "Exists", "");
				if(strCondition.equals("True"))
				{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "Retry", 1);}
				else
				{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "RETRY", 1);}
				if(strRole.contains("concierge"))
				{SENTRYMOBILE_RegisterUserRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver,"concierge");}
				else
				{SENTRYMOBILE_RegisterUserRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver,"parker");}
				SENTRYMOBILE_LoginAfterRegisteringUserEmailIdWithoutCaps(objDictionary, androiddriver, strRole);
			}
			else if(strDialogMessage.contains("No nearby parking spots available. Please retry"))
			{
				//This seems to be changing from RETRY to Retry
				strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Login", "RETRY", 1, "Exists", "");
				if(strCondition.equals("True"))
				{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "RETRY", 1);}
				else
				{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "Retry", 1);}
			}
			else if(strDialogMessage.contains("No nearby parking spots available."))
			{
				//This seems to be changing from OK to ok
				strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Login", "OK", 1, "Exists", "");
				if(strCondition.equals("True"))
				{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "OK", 1);}
				else
				{clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "Ok", 1);}
			}
			else if(strDialogMessage.contains("Do you want to enable biometric authentication for easier login?"))
			{
				clsCommonMobile.ClickLink(objDictionary, androiddriver, "Login", "NOT RIGHT NOW", 1);
			}
			else if(strDialogMessage.contains("With GPS disabled, you will only have access to your registered municipality : "+strMunicipality+". Please enable GPS to access other municipalities"))
			{}//Do Nothing
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver, "Unexpected Dialog appeared with the text (" + strDialogMessage + ")");}
		}
	}
