	public void SENTRYMOBILE_RegisterUserRememberMeOff(Map<String, String> objDictionary, AndroidDriver androiddriver)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		String strRole = "parker";
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = strUniqueId+objDictionary.get("strMunicipality");
		String strUserName = strMunicipality.replace(" ","").replace(",", "")+strRole+"@gmail.com";
		String strPassword = clsCommonWeb.SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		ClickButton(objDictionary, androiddriver, "Login", "Register",1);
		String strCondition = clsCommonMobile.ConditionalStepLink(objDictionary, androiddriver, "Register", "Select Municipality", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			clsCommonMobile.PopulateScrollableListbox(objDictionary, androiddriver, "Register", "Select Municipality", strMunicipality+", USA");
			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Register", "Continue",1);
		}
		PopulateAction(objDictionary, androiddriver, "Register", "Populate Login", "{T} First Name|{T} Last Name|{T} Email Id|{T} Confirm Email Id|{T} Password|{T} Confirm Password",strMunicipality.replace(" ", "").replace(",","")+"|"+strRole+"|"+strUserName+"|"+strUserName+"|"+strPassword+"|"+strPassword);
		ClickButton(objDictionary, androiddriver, "Register", "Remember me",1);
		ClickLink(objDictionary,androiddriver, "Register", "Submit", 1);
		VerificationPointText(objDictionary, androiddriver, "Register", "Dialog Message", 1, "Value", "You have successfully registered! Click OK to login. After logging in, you can go to Accounts to add money to your account.");
		ClickLink(objDictionary, androiddriver, "Register", "OK",1);
		VerificationPointPage(objDictionary, androiddriver, "Login", "Exists");
	}
