	public void SENTRYMOBILE_NavigateToPageUsingMenuButtons(Map<String, String> objDictionary,AndroidDriver androiddriver, String strPageName)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		WebElement objPageName = null;
		String strCurrentPage = "";String strButtonName = "";
		String strEnableUiautomator2 = objDictionary.get("strEnableUiautomator2");if(strEnableUiautomator2 == null){strEnableUiautomator2 = "False";}
		try
		{
			switch (strPageName)
			{
				case "Nearby Parking":
					strButtonName = "Spots";
					androiddriver.findElement(By.xpath(".//android.widget.RelativeLayout[1]/android.widget.HorizontalScrollView[1]/android.widget.LinearLayout[1]/android.widget.LinearLayout[1]")).click();
					try {Thread.sleep(1000);}catch (Exception e) {}//wait for meters to load
					break;
				case "Meter Payment":
					try {androiddriver.findElement(By.id("RETRY")).click();}catch (Exception e) {}
					strButtonName = "Pay for meter";
					if(strEnableUiautomator2.equals("False"))
					{
						clsCommonMobile.ClickButton(objDictionary, androiddriver, "Nearby Parking", "Pay for meter", 1);
					}
					else
					{
						androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.ViewGroup[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.widget.HorizontalScrollView[1]/android.widget.LinearLayout[1]/android.widget.LinearLayout[2]/android.widget.TextView[1]")).click();
					}
					break;
				case "Pay for lot":
				case "Lot Payment":
					strButtonName = "Pay for lots";
					strPageName = "Lot Permit Payment";
					androiddriver.findElement(By.xpath(".//android.widget.RelativeLayout[1]/android.widget.HorizontalScrollView[1]/android.widget.LinearLayout[1]/android.widget.LinearLayout[3]")).click();
					break;
				case "Parking Sessions":
					strButtonName = "Active session";
					strPageName = "Parking Sessions";
					//Phone Version Dependent
					//androiddriver.findElement(By.xpath(".//android.widget.RelativeLayout[1]/android.widget.HorizontalScrollView[1]/android.widget.LinearLayout[1]/android.widget.LinearLayout[4]")).click();
					androiddriver.findElement(By.xpath("(//android.widget.TextView[@resource-id=\"com.mpspark.consumer.mpsconsumer:id/textViewIcon\"])[4]")).click();
					break;
				case "Account Details":
					strButtonName = "Account";
					androiddriver.findElement(By.xpath(".//android.widget.RelativeLayout[1]/android.widget.HorizontalScrollView[1]/android.widget.LinearLayout[1]/android.widget.LinearLayout[5]")).click();
					break;
				default:
					UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The page ("+strPageName+") hasn't been added-"+strMethondName);
			}
		}
		catch (Exception e)
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The page button ("+strButtonName+") did not exist or the page attributes changed-"+strMethondName);}
		try {Thread.sleep(5000);}catch (Exception e) {}//wait for meters to load
		try{objPageName =androiddriver.findElement(By.id("com.mpspark.consumer.mpsconsumer:id/titleText"));strCurrentPage =  objPageName.getText();}
		catch(Exception e)
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Unable to locate current page object-"+strMethondName);}
		if(strCurrentPage.equals(""))
		{
			//Nearby Parking
			if(strEnableUiautomator2.equals("False"))
			{
				try{objPageName =androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.View[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.support.v4.view.ViewPager[1]/android.widget.RelativeLayout[1]/android.widget.LinearLayout[1]/android.widget.TextView[2]"));
				strCurrentPage =  objPageName.getText();}catch(Exception e){}
			}
			else
			{
				try{objPageName =androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.ViewGroup[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.support.v4.view.ViewPager[1]/android.widget.RelativeLayout[1]/android.widget.TextView[1]"));
				strCurrentPage =  objPageName.getText();}catch(Exception e){}
			}
			//try{objPageName =androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.View[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.support.v4.view.ViewPager[1]/android.widget.RelativeLayout[1]/android.widget.LinearLayout[1]/android.widget.TextView[1]"));
			//try{objPageName = androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.View[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.support.v4.view.ViewPager[1]/android.widget.RelativeLayout[1]/android.widget.LinearLayout[1]/android.widget.TextView[2]"));
			try{objPageName = androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.ViewGroup[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.support.v4.view.ViewPager[1]/android.widget.LinearLayout[1]/android.widget.ScrollView[1]/android.widget.LinearLayout[1]/android.widget.LinearLayout[1]/android.widget.TextView[2]"));
			strCurrentPage =  objPageName.getText();}catch(Exception e){}
			if(strCurrentPage.equals(""))
			{
				//Account Details
				try{objPageName =androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.view.ViewGroup[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.support.v4.view.ViewPager[1]/android.widget.RelativeLayout[1]/android.widget.LinearLayout[1]/android.widget.TextView[2]"));
				strCurrentPage =  objPageName.getText();}catch(Exception e){}
				if(strCurrentPage.equals(""))
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Unable to locate current page title object-"+strMethondName);}
			}
		}
		if(strCurrentPage.equals(strPageName))
		{Reporter.log("Navigated to the ("+strPageName+") page correctly");}
		else
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Current Page ("+strCurrentPage+") did not equal ("+strPageName+")");}
	}
	public void SENTRYMOBILE_PurchaseParkingDialogHandler(Map<String, String> objDictionary, AndroidDriver androiddriver, String strLicensePlateNumber)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		try
		{
			String strCondition = clsCommonMobile.ConditionalStepText(objDictionary,androiddriver, "Meter Payment", "Dialog Message", 1, "Exists", "");
			if(strCondition.equals("True"))
			{
				String strDialogMessage = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Dialog Message", 1, "strDialogMessage");
				if(strDialogMessage.contains("Insufficient funds available in Parker Account."))
				{
					//Navigate To Account Details and Add Money to Account
					clsCommonMobile.ClickLink(objDictionary, androiddriver, "Meter Payment", "Ok", 1);
					clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Account Details");
				    	try {Thread.sleep(1000);}catch (Exception e) {}//wait for meters to load
				    	clsCommonMobile.SENTRYMOBILE_AddMoneyToAccount(objDictionary, androiddriver);
				    	//Navigate to the Meter Payment and Purchase Parking
				    	clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
				    	try {Thread.sleep(2000);}catch (Exception e) {}//wait for meters to load
				    	clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
				    	String strCurrentLicencePlate = clsCommonMobile.StoreTextField(objDictionary, androiddriver, "Meter Payment", "License Plate", 1, "strVarLicencePlate");
					clsCommonMobile.ClickLink(objDictionary, androiddriver, "Meter Payment", strCurrentLicencePlate, 1);
					clsCommonMobile.PopulateScrollableListbox(objDictionary, androiddriver, "Meter Payment", "License Plate", strLicensePlateNumber);
					clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Purchase Parking", 1);
					clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "YES - PURCHASE", 1);
				}
				else if(strDialogMessage.contains("Parking expired"))
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Parking expired");}
				else if(strDialogMessage.contains("Device Rejected"))
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Device Rejected");}
				else if(strDialogMessage.contains("Oops, Something went wrong. Please try again."))
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Oops, Something went wrong. Please try again.-Check If Rabbit MQ is Down");}
				else if(strDialogMessage.contains("The meter is not currently responding"))
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The meter is not currently responding-Check If Rabbit MQ is Down");}
				else
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,strDialogMessage);}
			}
		}catch(Exception a) {}
	}
	public void SENTRYMOBILE_PurchaseParkingDialogHandler_ParkThenPay(Map<String, String> objDictionary, AndroidDriver androiddriver)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		Meter clsMeter = new Meter();
		String strHost = objDictionary.get("strHost");
		String strSpotNumber = objDictionary.get("strSpotNumber");
		String strVehicleDepartType = objDictionary.get("strVehicleDepartType");
		String strVehicleParkType = objDictionary.get("strVehicleParkType");
		String strCondition = clsCommonMobile.ConditionalStepText(objDictionary,androiddriver, "Meter Payment", "Dialog Message", 1, "Contains", "Insufficient funds available in Parker Account.");
		if(strCondition.equals("True"))
		{
			clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "vehicle_"+strVehicleDepartType+"_spot_"+strSpotNumber+".py");
			clsMeter.GlobalWait(objDictionary,  null, "{WaitUntilMeterVariableBegunEqualFalse} NA", 20,strSpotNumber,"Local");
			clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "vehicle_reset_spot_"+strSpotNumber+".py");
			clsCommonMobile.ClickLink(objDictionary, androiddriver, "Meter Payment", "Ok", 1);
	    	clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Account Details");try {Thread.sleep(1000);}catch (Exception e) {}
	    	clsCommonMobile.SENTRYMOBILE_AddMoneyToAccount(objDictionary, androiddriver);
	    	clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
	    	clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "vehicle_"+strVehicleParkType+"_spot_"+strSpotNumber+".py");
			clsMeter.GlobalWait(objDictionary,  null, "{WaitUntilMeterVariableBegunEqualTrue} NA", 20,strSpotNumber,"Local");
			clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Purchase Parking", 1);
			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "YES - PURCHASE", 1);
		}
		strCondition = clsCommonMobile.ConditionalStepText(objDictionary,androiddriver, "Meter Payment", "Dialog Message", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			strCondition = clsCommonMobile.ConditionalStepText(objDictionary,androiddriver, "Meter Payment", "Dialog Message", 1, "Contains", "Device Rejected");
			if(strCondition.equals("True"))
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Unable to Purchase Parking-Device Rejected");}
		}
	}
