	public void SENTRYMOBILE_ValidateFreeToParkMeterPaymentPageValues(Map<String, String> objDictionary,AndroidDriver androiddriver, String strLicensePlate, String strState, String strFreeTimeMinutes, String strFreeTimeFirstPayment)
    {
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strFreeParkingEndTime12 = objDictionary.get("strFreeParkingEndTime12");
		Reporter.log("The value ("+new SimpleDateFormat("HH:mm:ss").format(new Date())+") was stored as variable name strTimeWhenMeterPaymentPageAppeared");
    	clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
    	try {Thread.sleep(2000);}catch (Exception e) {}
    	clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
    	clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, androiddriver, strLicensePlate, strState);try {Thread.sleep(1000);}catch (Exception e) {}
    	String strCurrentTime_hmma = new SimpleDateFormat("h:mm a").format(new Date());
    	objDictionary.remove("strCurrentTime_hmma");objDictionary.put("strCurrentTime_hmma",strCurrentTime_hmma);
		String strCurrentTimeSeconds = new SimpleDateFormat("ss").format(new Date());
		Reporter.log("The value ("+strCurrentTimeSeconds+") strCurrentTimeSeconds"+"");
    	//Validate Free Parking Time
    	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Free Parking Message", 1, "Exists", "");
		if(strFreeParkingEndTime12.contains(":00"))
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Free Parking Time", 1, "Value", strFreeParkingEndTime12.replace(":00",""));}
		else
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Free Parking Time", 1, "Value", strFreeParkingEndTime12);}
		//Calculate Max Time
		String strMeterRemainingTimeSeconds = clsMeter.GetMeterRemainingTimeSeconds(objDictionary);
		double dblMeterRemainingTimeSeconds = Double.parseDouble(strMeterRemainingTimeSeconds);
		Reporter.log("dblMeterRemainingTimeSeconds: "+dblMeterRemainingTimeSeconds+"");
		double dblMeterRemainingTimeMinutes = dblMeterRemainingTimeSeconds/60;
		Reporter.log("dblMeterRemainingTimeMinutes: "+dblMeterRemainingTimeMinutes+"");
		int intMeterRemainingTimeMinutes = (int)Math.round(dblMeterRemainingTimeMinutes);
		Reporter.log("intMeterRemainingTimeMinutes: "+intMeterRemainingTimeMinutes+"");
		//Add To Dictionary to used by SENTRYMOBILE_ValidateFreeToParkMeterPaymentValuesWithBuyMaxTime
		objDictionary.remove("strMeterRemainingTimeMinutes");objDictionary.put("strMeterRemainingTimeMinutes",Integer.toString(intMeterRemainingTimeMinutes));
		String strMeterMaxDurationMinutes = objDictionary.get("strMeterMaxDurationMinutes");
		Reporter.log("strMeterMaxDurationMinutes: "+strMeterMaxDurationMinutes+"");
		int intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + Integer.parseInt(strMeterMaxDurationMinutes);
		String strMeterMaxtimeUsingRemainingTime = intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes / 60 + " Hrs " + intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes % 60 + " Mins";
		Reporter.log("The value ("+strMeterMaxtimeUsingRemainingTime+") strMeterMaxtimeUsingRemainingTime"+"");
		String strMeterMaxtimeUsingRemainingTimeMinusOne = intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes / 60 + " Hrs " + (intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes % 60-1) + " Mins";
		Reporter.log("The value ("+strMeterMaxtimeUsingRemainingTimeMinusOne+") strMeterMaxtimeUsingRemainingTimeMinusOne"+"");
		String strMeterMaxtimeUsingRemainingTimePlusOne = intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes / 60 + " Hrs " + (intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes % 60+1) + " Mins";
		Reporter.log("The value ("+strMeterMaxtimeUsingRemainingTimePlusOne+") strMeterMaxtimeUsingRemainingTimeMinusOne"+"");
		//Validate Max time
		strMeterMaxtimeUsingRemainingTime = "Max time : "+strMeterMaxtimeUsingRemainingTime;
		strMeterMaxtimeUsingRemainingTimeMinusOne = "Max time : "+strMeterMaxtimeUsingRemainingTimeMinusOne;
		strMeterMaxtimeUsingRemainingTimePlusOne = "Max time : "+strMeterMaxtimeUsingRemainingTimePlusOne;
		String strActualMaxtime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Max time", 1, "strActualMaxtime");
		//Add To Dictionary to used by SENTRYMOBILE_ValidateFreeToParkMeterPaymentValuesWithBuyMaxTime
		objDictionary.remove("strActualMaxtime");objDictionary.put("strActualMaxtime",strActualMaxtime);
		if(strActualMaxtime.equals(strMeterMaxtimeUsingRemainingTime))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxtimeUsingRemainingTime + ")"+"");}
		else if(strActualMaxtime.equals(strMeterMaxtimeUsingRemainingTimeMinusOne))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxtimeUsingRemainingTimeMinusOne + ")"+"");}
		else if(strActualMaxtime.equals(strMeterMaxtimeUsingRemainingTimePlusOne))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxtimeUsingRemainingTimePlusOne + ")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Max time) with index (1) did not equal (" + strMeterMaxtimeUsingRemainingTime + ") - actual value (" + strActualMaxtime + ")");}
		//Store Minutes Purchased
		String strMeterCardIncrementMinutes = objDictionary.get("strMeterCardIncrementMinutes");
		int intTotalTimePurchased = Integer.parseInt(strMeterCardIncrementMinutes)+Integer.parseInt(strFreeTimeFirstPayment);
		String strMobileTimePurchased = clsCommonMobile.StoreTextField(objDictionary, androiddriver, "Meter Payment", "Purchase Time", 1, "strMobileTimePurchased");
		objDictionary.remove("strMobileTimePurchased");objDictionary.put("strMobileTimePurchased", strMobileTimePurchased.replaceAll("[^0-9.]", ""));
    	//Validate Purchase Time
    	clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Meter Payment","Purchase Time", 1, "Value", intTotalTimePurchased+" Mins");
    	//Calculate Valid Until Time
    	String strValidUntilMinutes = Integer.toString(intMeterRemainingTimeMinutes + Integer.parseInt(strMobileTimePurchased.replaceAll("[^0-9.]", "")));
    	String strValidUntilMinutesMinusOne = Integer.toString(intMeterRemainingTimeMinutes -1 + Integer.parseInt(strMobileTimePurchased.replaceAll("[^0-9.]", "")));
    	String strValidUntilMinutesPlusOne = Integer.toString(intMeterRemainingTimeMinutes +1 + Integer.parseInt(strMobileTimePurchased.replaceAll("[^0-9.]", "")));
    	//Valid until Time
    	String strActualValueUntil = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Valid until", 1, "strActualValueUntil");
    	Reporter.log("The value ("+strValidUntilMinutes+") strValidUntilMinutes"+"");
    	Reporter.log("The value ("+strValidUntilMinutesMinusOne+") strValidUntilMinutesMinusOne"+"");
    	Reporter.log("The value ("+strValidUntilMinutesPlusOne+") strValidUntilMinutesPluseOne"+"");
    	String strValidUntilTime = AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutes,"h:mm a").replace(":00","");
    	String strValidUntilTimeMinusOne = AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutesMinusOne,"h:mm a").replace(":00","");
    	String strValidUntilTimePlusOne = AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutesPlusOne,"h:mm a").replace(":00","");
    	strValidUntilTime = "Valid until "+strValidUntilTime;
    	strValidUntilTimeMinusOne = "Valid until "+strValidUntilTimeMinusOne;
    	strValidUntilTimePlusOne = "Valid until "+strValidUntilTimePlusOne;
    	Reporter.log("strValidUntilTime equalled ("+strValidUntilTime+")");
    	Reporter.log("strValidUntilTimeMinusOne equalled("+strValidUntilTimeMinusOne+")");
    	if(strActualValueUntil.equals(strValidUntilTime))
		{Reporter.log("The Text (Valid until) with index (1) equalled (" + strValidUntilTime + ")"+"");}
		else if(strActualValueUntil.equals(strValidUntilTimeMinusOne))
		{Reporter.log("The Text (Valid until) with index (1) equalled (" + strValidUntilTimeMinusOne + ")"+"");}
		else if(strActualValueUntil.equals(strValidUntilTimePlusOne))
		{Reporter.log("The Text (Valid until) with index (1) equalled (" + strValidUntilTimePlusOne + ")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Valid until) with index (1) did not equal (" + strValidUntilTime + ") - actual value (" + strActualValueUntil + ")");}
	}
	public void SENTRYMOBILE_ValidateFreeToParkMeterPaymentPageValuesWithBuyMaxTime(Map<String, String> objDictionary,AndroidDriver androiddriver, String strLicensePlate, String strState, String strFreeTimeMinutes, String strFreeTimeFirstPayment)
    {
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		clsCommonMobile.SENTRYMOBILE_ValidateFreeToParkMeterPaymentPageValues(objDictionary, androiddriver, strLicensePlate, "Alabama", strFreeTimeMinutes, strFreeTimeFirstPayment);
		//Click Purchase Max Time
	    	clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Buy Max Time", 1);
	    	clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Go Back", 1);
	    	//Validate Purchase Time
	    	String strActualMaxtime = objDictionary.get("strActualMaxtime");//From-SENTRYMOBILE_ValidateFreeToParkMeterPaymentPageValues
	    	clsCommonMobile.VerificationPointTextField(objDictionary, androiddriver, "Meter Payment","Purchase Time", 1, "Value", strActualMaxtime.replace("Max time : ",""));
	    	//Calculate Valid until
	    	String strMeterRemainingTimeSeconds = clsMeter.GetMeterRemainingTimeSeconds(objDictionary);
		double dblMeterRemainingTimeSeconds = Double.parseDouble(strMeterRemainingTimeSeconds);
		Reporter.log("dblMeterRemainingTimeSeconds: "+dblMeterRemainingTimeSeconds+"");
		double dblMeterRemainingTimeMinutes = dblMeterRemainingTimeSeconds/60;
		Reporter.log("dblMeterRemainingTimeMinutes: "+dblMeterRemainingTimeMinutes+"");
		String strMeterMaxDurationMinutes = objDictionary.get("strMeterMaxDurationMinutes");//From-SENTRYMOBILE_ValidateFreeToParkMeterPaymentPageValues
		Reporter.log("strMeterMaxDurationMinutes: "+strMeterMaxDurationMinutes+"");
		String strMeterRemainingTimeMinutes = objDictionary.get("strMeterRemainingTimeMinutes");
		int intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes = Integer.parseInt(strMeterRemainingTimeMinutes) + Integer.parseInt(strMeterMaxDurationMinutes);
		String strMeterMaxtimeUsingRemainingTime = intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes / 60 + " Hrs " + intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes % 60 + " Mins";
		Reporter.log("The value ("+strMeterMaxtimeUsingRemainingTime+") strMeterMaxtimeUsingRemainingTime"+"");
		String strMeterMaxtimeUsingRemainingTimeMinusOne = intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes / 60 + " Hrs " + (intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes % 60-1) + " Mins";
		Reporter.log("The value ("+strMeterMaxtimeUsingRemainingTimeMinusOne+") strMeterMaxtimeUsingRemainingTimeMinusOne"+"");
		String strMeterMaxtimeUsingRemainingTimePlusOne = intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes / 60 + " Hrs " + (intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes % 60+1) + " Mins";
		Reporter.log("The value ("+strMeterMaxtimeUsingRemainingTimePlusOne+") strMeterMaxtimeUsingRemainingTimePlusOne"+"");
		//Validate Meter Amount
		String strMeterCardIncrementMinutes = objDictionary.get("strMeterCardIncrementMinutes");
		double dblTotalCost = Integer.parseInt(strMeterMaxDurationMinutes)/Integer.parseInt(strMeterCardIncrementMinutes) * .25;
	    	DecimalFormat dFormat = new DecimalFormat("#.00");
	    	System.out.println("$" + dFormat.format(dblTotalCost));
	    	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Meter Amount", 1, "Value", "$" + dFormat.format(dblTotalCost));//Bug 127544231
	    	//Validate Valid until
	    	String strActualValueUntil = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Valid until", 1, "strActualValueUntil");
	    	String strCurrentTime_hmma = objDictionary.get("strCurrentTime_hmma");
	    	String strValidUntilTime = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, Integer.toString(intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes),"h:mm a").replace(":00","");
	    	String strValidUntilTimeMinusOne = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, Integer.toString(intMeterMaxDurationMinutesWithMeterRemainingTimeMinutes),"h:mm a").replace(":00","");
	    	try {Thread.sleep(1500);}catch (Exception f) {}
		//Validate Valid until
	    	if(strActualValueUntil.equals(strValidUntilTime))
		{Reporter.log("The Text (Valid until) with index (1) equalled (" + strValidUntilTime + ")"+"");}
		else if(strActualValueUntil.equals(strValidUntilTimeMinusOne))
		{Reporter.log("The Text (Valid until) with index (1) equalled (" + strValidUntilTimeMinusOne + ")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Valid until) with index (1) did not equal (" + strValidUntilTime + ") - actual value (" + strActualValueUntil + ")");}
	}
	public String SENTRYMOBILE_PurchaseMeterfTime_IncrementTimePurchased_ParkThenPay(Map<String, String> objDictionary,AndroidDriver androiddriver, String strLicensePlateNumber, String strState, int intAddIncrementValue)
    {
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		String strHost = objDictionary.get("strHost");
		String strSpotNumber = objDictionary.get("strSpotNumber");
		String strVehicleParkType = objDictionary.get("strVehicleParkType");
		String strMeterName = objDictionary.get("strMeterName");
		//Wait for GPS Map to Load
		try {Thread.sleep(3000);}catch (Exception e) {}
		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
		try {Thread.sleep(2000);}catch (Exception e) {}
		clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
		clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, androiddriver, strLicensePlateNumber, strState);
		try {Thread.sleep(1000);}catch (Exception e) {}
		//Increment Parking
		int intAddCounter = 0;
		while (intAddCounter < intAddIncrementValue)
		{
			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "+", 1);
			intAddCounter++;
        }
		String strTotalFee = StoreText(objDictionary, androiddriver, "Meter Payment", "Meter Amount", 1, "strTotalFee");
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Purchase Parking", 1);
		String strParkingFee = SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee(objDictionary, androiddriver, strTotalFee,"1");
		//Pay the Park
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "YES - PURCHASE", 1);
		clsMeter.METER_MeterWaitWithMessage(objDictionary, 30, "Wait 30 seconds before parking");
		clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "vehicle_"+strVehicleParkType+"_spot_"+strSpotNumber+".py");
		clsMeter.GlobalWait(objDictionary,  null, "{WaitUntilMeterVariableBegunEqualTrue} NA", 20,strSpotNumber,"Local");
		//Purchase Parking Dialog Handler
		clsCommonMobile.SENTRYMOBILE_PurchaseParkingDialogHandler(objDictionary, androiddriver,strLicensePlateNumber);
		//Spot:
		clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "testautof_touch_screen.py");
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Spot", 1, "Value", "Spot : "+strMeterName);
		//License Plate Number
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "License Plate Number", 1, "Value", strLicensePlateNumber);
		//Validate Parked at
		String strParkingSessionsParkedAtTime = objDictionary.get("strParkingSessionsParkedAtTime");
		String strParkingSessionsParkedAtTimeMinusOne = objDictionary.get("strParkingSessionsParkedAtTimeMinusOne");
		String strParkingSessionsParkedAtTimePlusOne = objDictionary.get("strParkingSessionsParkedAtTimePlusOne");
		String strActualParkingSessionsParkedAtTime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Parked at", 1, "strActualParkingSessionsParkedAtTime");
		if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTime))
		{Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+ strParkingSessionsParkedAtTime+")"+"");}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimeMinusOne))
		{Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimeMinusOne+")"+"");}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimePlusOne))
		{Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimePlusOne+")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Parked at) with index (1) did not equal (Parked " + strParkingSessionsParkedAtTime + ") - actual value (" + strActualParkingSessionsParkedAtTime + ")");}
		//Parking Expires in
		String strMeterRemainingTimeSeconds = clsMeter.GetMeterRemainingTimeSeconds(objDictionary);
		double dblMeterRemainingTimeSeconds = Double.parseDouble(strMeterRemainingTimeSeconds);
		Reporter.log("dblMeterRemainingTimeSeconds: "+dblMeterRemainingTimeSeconds+"");
		double dblMeterRemainingTimeMinutes = dblMeterRemainingTimeSeconds/60;
		Reporter.log("dblMeterRemainingTimeMinutes: "+dblMeterRemainingTimeMinutes+"");
		int intMeterRemainingTimeMinutes = (int)Math.round(dblMeterRemainingTimeMinutes);
		Reporter.log("intMeterRemainingTimeMinutes: "+intMeterRemainingTimeMinutes+"");
		//Validate Parking Expires in
		String strActualParkingExpiresIn = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Parking Expires in", 1, "strActualParkingExpiresIn");
		int intMeterRemainingTimeMinutesMinusOne = intMeterRemainingTimeMinutes -1;
		if(strActualParkingExpiresIn.equals("Parking expires in "+intMeterRemainingTimeMinutes+" Mins"))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled (Parking expires in "+intMeterRemainingTimeMinutes+" Mins)"+"");}
		else if(strActualParkingExpiresIn.equals("Parking expires in "+intMeterRemainingTimeMinutesMinusOne+" Mins"))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled (Parking expires in "+intMeterRemainingTimeMinutesMinusOne+" Mins)"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Parking expires in) with index (1) did not equal (Parking expires in "+intMeterRemainingTimeMinutes+" Mins) - actual value (" + strActualParkingExpiresIn + ")");}
		return strParkingFee;
    }
	public void SENTRYMOBILE_DisconnectOn_ValidateRateToFreeMeterPaymentPageValues(Map<String, String> objDictionary,AndroidDriver androiddriver, String strLicensePlate, String strState, String strFreeTimeMinutes)
    {
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		Reporter.log("The value ("+new SimpleDateFormat("HH:mm:ss").format(new Date())+") was stored as variable name strTimeWhenMeterPaymentPageAppeared"+"");
	    	clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
	    	try {Thread.sleep(2000);}catch (Exception e) {}
	    	clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
	    	SENTRYMOBILE_CheckForDialogBoxAfterSelectingSpot(objDictionary,androiddriver);
	    	String strCurrentTime_hmma = new SimpleDateFormat("h:mm a").format(new Date());
	    	clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, androiddriver, strLicensePlate, strState);try {Thread.sleep(1000);}catch (Exception e) {}
	    	//Add To Dictionary to used by ANDROID_RateToFree_UpdateRateBlock_ParkThenPay_BuyMaxTime_ValidateMeterPaymentValues
	    	objDictionary.remove("strCurrentTime_hmma");objDictionary.put("strCurrentTime_hmma",strCurrentTime_hmma);
		String strCurrentTimeSeconds = new SimpleDateFormat("ss").format(new Date());
		Reporter.log("The value ("+strCurrentTimeSeconds+") strCurrentTimeSeconds"+"");
	    	////Store Minimum Minutes Purchase Minutes
	    	String strMinimumPurchaseMinutes = clsCommonMobile.StoreTextField(objDictionary, androiddriver, "Meter Payment", "Purchase Time", 1, "strMinimumPurchaseMinutes").replaceAll("[^0-9.]", "");
	    	////Store Purchase Price
	    	clsCommonMobile.StoreTextField(objDictionary, androiddriver, "Meter Payment", "Purchase Price", 1, "strMinimuPurchasePrice").replaceAll("[^0-9.]", "");
	    	//Calculate Max Time
	    	String strFreeParkingStartTime12 = objDictionary.get("strFreeParkingStartTime12");
	    	SimpleDateFormat formater=new SimpleDateFormat("h:mm a");
	    	try
	    	{
		    	long d1=formater.parse(strFreeParkingStartTime12).getTime();
		    	long d2=formater.parse(strCurrentTime_hmma).getTime();
		    	int intMeterMaxtime = (int)(d1-d2) / (60 * 1000) % 60;
		    	int intMeterMaxtimeMinusOne = intMeterMaxtime -1;
		    	//Validate Max time
			String strMeterMaxtimeUsingRemainingTime = "Max time : "+intMeterMaxtime+" Mins";
			String strMeterMaxtimeUsingRemainingTimeMinusOne = "Max time : "+intMeterMaxtimeMinusOne+" Mins";
			String strActualMaxtime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Max time", 1, "strActualMaxtime");
			//Add To Dictionary to used by SENTRYMOBILE_ValidateFreeToParkMeterPaymentValuesWithBuyMaxTime
			if(strActualMaxtime.equals(strMeterMaxtimeUsingRemainingTime))
			{
				Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxtimeUsingRemainingTime + ")"+"");
				objDictionary.remove("strActualMaxtimeMinutes");objDictionary.put("strActualMaxtimeMinutes",Integer.toString(intMeterMaxtime));
			}
			else if(strActualMaxtime.equals(strMeterMaxtimeUsingRemainingTimeMinusOne))
			{
				Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxtimeUsingRemainingTimeMinusOne + ")"+"");
				objDictionary.remove("strActualMaxtimeMinutes");objDictionary.put("strActualMaxtimeMinutes",Integer.toString(intMeterMaxtimeMinusOne));
			}
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Max time) with index (1) did not equal (" + strMeterMaxtimeUsingRemainingTime + ") - actual value (" + strActualMaxtime + ")");}
		}catch (Exception e) {}
		//Calculate Valid Until Time
	    	int intMeterRemainingTimeMinutes = Integer.parseInt(strMinimumPurchaseMinutes);
	    	String strValidUntilMinutes = Integer.toString(intMeterRemainingTimeMinutes);
	    	String strValidUntilMinutesMinusOne = Integer.toString(intMeterRemainingTimeMinutes -1);
	    	//Validate Valid until Time
	    	String strActualValueUntil = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Valid until", 1, "strActualValueUntil");
	    	Reporter.log("The value ("+strValidUntilMinutes+") strValidUntilMinutes"+"");
	    	Reporter.log("The value ("+strValidUntilMinutesMinusOne+") strValidUntilMinutesMinusOne"+"");
	    	String strValidUntilTime = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutes,"h:mm a");
	    	String strValidUntilTimeMinusOne = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutesMinusOne,"h:mm a");
	    	strValidUntilTime = "Valid until "+strValidUntilTime;
	    	strValidUntilTimeMinusOne = "Valid until "+strValidUntilTimeMinusOne;
	    	if(strActualValueUntil.equals(strValidUntilTime))
		{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTime + ")"+"");}
		else if(strActualValueUntil.equals(strValidUntilTimeMinusOne))
		{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTimeMinusOne + ")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Valid until) with index (1) did not equal (" + strValidUntilTime + ") - actual value (" + strActualValueUntil + ")");}
		//Validate Free Parking Starts At Time
	    	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Free Parking Starts At", 1, "Value", strFreeParkingStartTime12);
    }

	public void SENTRYMOBILE_ValidateFreeToRateParkingSessionValues(Map<String, String> objDictionary, AndroidDriver androiddriver,String strLicensePlateNumber, String strMeterTimeIncrementValue, String strFreeTimeFirstPayment, String strTotalFee,String strFirstPaymentFlag, String strFreeTimeMinutes)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		Meter clsMeter = new Meter();
		String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
		String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
		//CalculateRemainingFreeTime
		int intMeterRemainingFreeTimeMinutes = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null, strRemainingFreeTimeStart, strFreeTimeMinutes);
		int intMeterRemainingTimeMinutes = 0;
		if(strFirstPaymentFlag.equals("True"))
		{
			intMeterRemainingTimeMinutes = intMeterRemainingFreeTimeMinutes + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue);
		}
		else if(strFirstPaymentFlag.equals("PRT")||strFirstPaymentFlag.equals("PMT"))
		{
			String strMaximumDuration = objDictionary.get("strMaximumDuration");
			intMeterRemainingTimeMinutes = intMeterRemainingFreeTimeMinutes + Integer.parseInt(strFreeTimeFirstPayment) + (Integer.parseInt(strMaximumDuration));
		}
		else
		{
			intMeterRemainingTimeMinutes = intMeterRemainingFreeTimeMinutes + Integer.parseInt(strFreeTimeFirstPayment) + (Integer.parseInt(strMeterTimeIncrementValue) *2);
		}
		//VMT: Validate Meter Time
	  	clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null,  intMeterRemainingTimeMinutes,"1");
		//Validate SpotAndLicensePlateNumber
		clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary,androiddriver,strLicensePlateNumber);
		//Validate Parked at Time
		clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//ValidateParkingSessionsValidUntil
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.SENTRYMOBILE_ValidateParkingSessionsParkingExpiresIn(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//ValidateParkingSessionsIncludesFreeTime
		SENTRYMOBILE_ValidateParkingSessionsIncludeFreeTime(objDictionary,androiddriver, intMeterRemainingFreeTimeMinutes);
		//Validate Receipt Values
		SENTRYMOBILE_ValidateReceiptValues(objDictionary, androiddriver, strMeterTimeIncrementValue, strFirstPaymentFlag, strFreeTimeFirstPayment, intMeterRemainingFreeTimeMinutes);
	}

	public void SENTRYMOBILE_ValidateFreeToRateParkingSessionValues2(Map<String, String> objDictionary, AndroidDriver androiddriver,String strLicensePlateNumber, String strMeterTimeIncrementValue, String strFreeTimeFirstPayment, String strTotalFee,String strFirstPaymentFlag, String strFreeTimeMinutes)throws Exception
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
		String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
		//CalculateRemainingFreeTime
		//Added + 1 for Sentry Link Version 7.9.11
		int intMeterRemainingFreeTimeMinutes = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes) + 1;
		int intMeterRemainingTimeMinutes = intMeterRemainingFreeTimeMinutes + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue);
		//VMT: Validate Meter Time
	  	clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null,  intMeterRemainingTimeMinutes,"1");
		//Validate SpotAndLicensePlateNumber
		clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary,androiddriver,strLicensePlateNumber);
		//Validate Parked at TimeclsMeter.METER_CalculateRemainingFreeTime
		clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		String strPurchasedAt =  clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//CalculateRemainingFreeTime
		int intMeterRemainingFreeTimeMinutesForValidUntil = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes);
		int intMeterRemainingTimeMinutesForValidUntil = intMeterRemainingFreeTimeMinutesForValidUntil + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue);
		//ValidateParkingSessionsValidUntil
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsParkingExipresIn(objDictionary,androiddriver,intMeterRemainingTimeMinutesForValidUntil);
		//CalculateRemainingFreeTime
//		int intMeterRemainingFreeTimeMinutesForIncludesFree = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes);
		//ValidateParkingSessionsIncludesFreeTime
		SENTRYMOBILE_ValidateParkingSessionsIncludeFreeTime(objDictionary,androiddriver, intMeterRemainingFreeTimeMinutes);
		//Calculate Receipt Data
		double dblMeterTimeIncrementValue = Double.parseDouble(strMeterTimeIncrementValue);
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		String strPaymentFees = "";
		int intTimePurchase1 = 0;
		if(strFirstPaymentFlag.equals("True"))
		{
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateFirstPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMeterTimeIncrementValue);
		}
		else
		{
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateSubsequentPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMeterTimeIncrementValue)/2;
		}
		String strAmountPaid1 = clsCommonWeb.SENTRYLINK_CalculateCreditCardAmount(dblMeterTimeIncrementValue, strMeterTimeIncrementValue,dFormat);
		Double dblTotalAmountPaid = Double.parseDouble(strPaymentFees.replace("$","")) + Double.parseDouble(strAmountPaid1.replace("$",""));
		String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
		if(strConditional.equals("False"))
		{
			//clsCommonMobile.GlobalWait(objDictionary, iosdriver, "Parking Sessions", "{ButtonExists} Parking Sessions~DropDownArrow", 15);
			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);
			try {Thread.sleep(1500);}catch (Exception e) {}
		}
//	    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
//		String strPurchaseAt = dateFormat.format(date);
		//Validate Receipt
		try {Thread.sleep(5000);}catch (Exception e) {}
		clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Amount Paid", 10);
		if(strPaymentFees.equals("$0.00"))
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblTotalAmountPaid));}
		else
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblTotalAmountPaid)+" (Conv. fee "+strPaymentFees+")");}
		//Validate Time Purchased
  		String strTimePurchased = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurchased");
  		int intTimePurchase1PlusOne = intTimePurchase1 +1;
  		int intTimePurchase1MinusOne = intTimePurchase1 -1;
		if(strTimePurchased.contains(intTimePurchase1PlusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1PlusOne+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchase1+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchase1MinusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1MinusOne+" Minutes)");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Time purchased did not contain ("+intTimePurchase1+") - actual value ("+strTimePurchased+")");}
		//Validate Purchased At
		strPurchasedAt = strPurchasedAt.replace("Today at ", "");
		String strPurchasedAtPlusOne = clsCommonMobile.AddTimeToExistingTime(strPurchasedAt, "1","h:mm a");
		String strActualPurchasedAt = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "strActualPurchasedAt");
		if(strActualPurchasedAt.contains(strPurchasedAt))
		{Reporter.log("The Text (Purchased At) with index (1) contained (" + strPurchasedAt + ")");}
		else if(strActualPurchasedAt.contains(strPurchasedAtPlusOne))
		{Reporter.log("The Text (Purchased At) with index (1) contained (" + strPurchasedAtPlusOne + ")-Plus 1");}
		else
		{UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Purchased At) with index (1) did not contain (" + strPurchasedAt + ") - actual value (" + strActualPurchasedAt + ")");}
	}



	//Validation Function
	public void SENTRYMOBILE_ValidateParkingSessionsParkingExpiresIn(Map<String, String> objDictionary,AndroidDriver androiddriver, int intMeterRemainingTimeMinutes)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		int intMeterRemainingTimeMinutesPlusOne = intMeterRemainingTimeMinutes +1;
		int intMeterRemainingTimeMinutesMinusOne = intMeterRemainingTimeMinutes -1;
		String strActualParkingExpiresIn = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Parking Expires in", 1, "strActualParkingExpiresIn");
		String strMeterRemainingTimeMinutesPlusOne = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterRemainingTimeMinutesPlusOne));
		String strMeterRemainingTimeMinutes = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterRemainingTimeMinutes));
		String strMeterRemainingTimeMinutesMinusOne = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterRemainingTimeMinutesMinusOne));
		if (intMeterRemainingTimeMinutesPlusOne > 60)
		{
			int hours = intMeterRemainingTimeMinutesPlusOne / 60;int minutes = intMeterRemainingTimeMinutesPlusOne % 60;
			if(hours == 1){strMeterRemainingTimeMinutesPlusOne = Integer.toString(hours)+" Hr "+Integer.toString(minutes)+" Mins";}
			else{strMeterRemainingTimeMinutesPlusOne = Integer.toString(hours)+" Hrs "+Integer.toString(minutes)+" Mins";}
		}
		if (intMeterRemainingTimeMinutes > 60)
		{
			int hours = intMeterRemainingTimeMinutes / 60;int minutes = intMeterRemainingTimeMinutes % 60;
			if(hours == 1){strMeterRemainingTimeMinutes = Integer.toString(hours)+" Hr "+Integer.toString(minutes)+" Mins";}
			else{strMeterRemainingTimeMinutes = Integer.toString(hours)+" Hrs "+Integer.toString(minutes)+" Mins";}
		}
		if(intMeterRemainingTimeMinutesMinusOne > 60)
		{
			int hours = intMeterRemainingTimeMinutesMinusOne / 60;int minutes = intMeterRemainingTimeMinutesMinusOne % 60;
			if(hours == 1){strMeterRemainingTimeMinutesMinusOne = Integer.toString(hours)+" Hr "+Integer.toString(minutes)+" Mins";}
			else{strMeterRemainingTimeMinutesMinusOne = Integer.toString(hours)+" Hrs "+Integer.toString(minutes)+" Mins";}
		}
		String strExpectedParkingExpiredInPlusOne =  "Parking expires in "+strMeterRemainingTimeMinutesPlusOne;
		String strExpectedParkingExpiredIn =  "Parking expires in "+strMeterRemainingTimeMinutes;
		String strExpectedParkingExpiredInMinusOne =  "Parking expires in "+strMeterRemainingTimeMinutesMinusOne;
		if(strActualParkingExpiresIn.contains(strExpectedParkingExpiredInPlusOne))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled ("+strExpectedParkingExpiredInPlusOne+")-Actual");}
		else if(strActualParkingExpiresIn.contains(strExpectedParkingExpiredIn))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled ("+strExpectedParkingExpiredIn+")-Actual");}
		else if(strActualParkingExpiresIn.contains(strExpectedParkingExpiredInMinusOne))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled ("+strExpectedParkingExpiredInMinusOne+")-Minus1");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Parking Expires in) with index (1) did not equal ("+strExpectedParkingExpiredIn+")-Actual Value ("+strActualParkingExpiresIn+")");}
	}
	public void SENTRYMOBILE_ValidateReceiptValues(Map<String, String> objDictionary, AndroidDriver androiddriver,String strMeterTimeIncrementValue,String strFirstPaymentFlag,String strFreeTimeFirstPayment,int intMeterRemainingFreeTimeMinutes)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		int intTimePurchase1 = 0;
		double dblMeterTimeIncrementValue = Double.parseDouble(strMeterTimeIncrementValue);
		String strPaymentFees = "";
		if(strFirstPaymentFlag.equals("True"))
		{
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateFirstPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMeterTimeIncrementValue) + Integer.parseInt(strFreeTimeFirstPayment) + intMeterRemainingFreeTimeMinutes;
		}
		else if(strFirstPaymentFlag.equals("PRT"))
		{
			//Need to get Time purchaed from meter
			String strMaximumDuration = objDictionary.get("strMaximumDuration");
			dblMeterTimeIncrementValue = Double.parseDouble(strMaximumDuration) - Integer.parseInt(strMeterTimeIncrementValue);
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateFirstPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMaximumDuration) - Integer.parseInt(strMeterTimeIncrementValue);
		}
		else if(strFirstPaymentFlag.equals("PMT"))
		{
			//Need to get Time purchaed from meter
			String strMaximumDuration = objDictionary.get("strMaximumDuration");
			dblMeterTimeIncrementValue = Double.parseDouble(strMaximumDuration);
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateFirstPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMaximumDuration);
		}
		else
		{
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateSubsequentPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMeterTimeIncrementValue)/2;
		}
		String strAmountPaid1 = clsCommonWeb.SENTRYLINK_CalculateCreditCardAmount(dblMeterTimeIncrementValue, strMeterTimeIncrementValue,dFormat);
		Double dblTotalAmountPaid = Double.parseDouble(strPaymentFees.replace("$","")) + Double.parseDouble(strAmountPaid1.replace("$",""));
		String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
		if(strConditional.equals("False")){clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);try {Thread.sleep(1500);}catch (Exception e) {}}
		//Validate Receipt
		clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Amount Paid", 10);
		if(strPaymentFees.equals("$0.00"))
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblTotalAmountPaid));}
		else
		{clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblTotalAmountPaid)+" (Conv. fee "+strPaymentFees+")");}
		//Validate Time Purchased
		try {Thread.sleep(1000);}catch (Exception e) {}
		String strTimePurchased = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurchased");
  		int intTimePurchase1PlusOne = intTimePurchase1 +1;
  		int intTimePurchase1MinusOne = intTimePurchase1 -1;
		if(strTimePurchased.contains(intTimePurchase1PlusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1PlusOne+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchase1+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchase1MinusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1MinusOne+" Minutes)");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Time purchased did not contain ("+intTimePurchase1+") - actual value ("+strTimePurchased+")");}
		//Validate Purchased At  //Second Payment Time?
		String strExpectedPurchasedAtTime = clsMeter.METER_ConvertSubsequentPaymentTimeTo_hmma(objDictionary);
		String strExpectedPurchasedAtTimPlus1 = clsCommonMobile.AddTimeToExistingTime(strExpectedPurchasedAtTime, "1", "h:mm a");
		String strActualPurchasedAtTime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "strActualPurchasedAtTime");
		if(strActualPurchasedAtTime.contains(strExpectedPurchasedAtTime))
		{Reporter.log("The Text (Purchased At) with index (1) contained (" + strExpectedPurchasedAtTime + ")");}
		else if(strActualPurchasedAtTime.contains(strExpectedPurchasedAtTimPlus1))
		{Reporter.log("The Text (Purchased At) with index (1) contained (" + strExpectedPurchasedAtTimPlus1 + ")");}
		else
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Purchased At) with index (1) did not contain (" + strExpectedPurchasedAtTime + ") - actual value (" + strActualPurchasedAtTime + ")");}
	}

	public void SENTRYMOBILE_ValidateFreeToRateParkingSessionValues(Map<String, String> objDictionary, AndroidDriver androiddriver,String strLicensePlateNumber, String strMeterTimeIncrementValue, String strFreeTimeFirstPayment, String strTotalFee,String strFirstPaymentFlag, String strCreditCardIncrementTime, String strFreeTimeMinutes, int intMeterRemainingFreeTimeMinutes)throws Exception
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
		String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
		//CalculateRemainingFreeTime
		int intMeterRemainingTimeMinutes = intMeterRemainingFreeTimeMinutes + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strCreditCardIncrementTime);
		//Take Android Screen Shot
		clsCommonMobile.TakeAndroidScreenShot(androiddriver,objDictionary,"FreeTorRateParkingValues");
  		//VMT: Validate Meter Time
	  	clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null,  intMeterRemainingTimeMinutes,"1");
		//Validate SpotAndLicensePlateNumber
		clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary,androiddriver,strLicensePlateNumber);
		//Validate Parked at Time
		clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//CalculateRemainingFreeTime
		int intMeterRemainingFreeTimeMinutesForValidUntil = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes);
		int intMeterRemainingTimeMinutesForValidUntil = intMeterRemainingFreeTimeMinutesForValidUntil + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strCreditCardIncrementTime);
		//ValidateParkingSessionsValidUntil
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,intMeterRemainingTimeMinutesForValidUntil);
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsParkingExipresIn(objDictionary,androiddriver,intMeterRemainingTimeMinutesForValidUntil);
		//ValidateParkingSessionsIncludesFreeTime
		SENTRYMOBILE_ValidateParkingSessionsIncludeFreeTime(objDictionary,androiddriver, intMeterRemainingFreeTimeMinutes);
		//Calculate Receipt Data
		double dblMeterTimeIncrementValue = Double.parseDouble(strMeterTimeIncrementValue);
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		String strPaymentFees = "";
		int intTimePurchase1 = 0;
		if(strFirstPaymentFlag.equals("True"))
		{
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateFirstPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strMeterTimeIncrementValue);
		}
		else
		{
			strPaymentFees = clsCommonWeb.SENTRYLINK_CalculateSubsequentPaymentFee(objDictionary);
			intTimePurchase1 = Integer.parseInt(strCreditCardIncrementTime)/2 - Integer.parseInt(strFreeTimeFirstPayment);
		}
		String strAmountPaid1 = clsCommonWeb.SENTRYLINK_CalculateCreditCardAmount(dblMeterTimeIncrementValue, strMeterTimeIncrementValue,dFormat);
		Double dblTotalAmountPaid = Double.parseDouble(strPaymentFees.replace("$","")) + Double.parseDouble(strAmountPaid1.replace("$",""));
		String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
		if(strConditional.equals("False")){clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);try {Thread.sleep(1500);}catch (Exception e) {}}
	    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
		String strPurchaseAt = dateFormat.format(date);
		//Validate Receipt
		clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Amount Paid", 10);
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblTotalAmountPaid)+" (Conv. fee "+strPaymentFees+")");
  		//try {Thread.sleep(2500);}catch (Exception e) {}
		String strTimePurchased = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurchased");
  		int intTimePurchase1PlusOne = Integer.parseInt(strFreeTimeFirstPayment) + intTimePurchase1 +1;
    	int intTimePurchased = Integer.parseInt(strFreeTimeFirstPayment) + intTimePurchase1;
  		int intTimePurchase1MinusOne =  Integer.parseInt(strFreeTimeFirstPayment) + intTimePurchase1 -1;
    	if(strTimePurchased.contains(intTimePurchase1PlusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1PlusOne+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchased+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchase1MinusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1MinusOne+" Minutes)");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Time purchased did not contain ("+intTimePurchased+") - actual value ("+strTimePurchased+")");}
		try {Thread.sleep(1500);}catch (Exception e) {}
    	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "Contains", strPurchaseAt);
    }
	public void SENTRYMOBILE_CheckForDialogBoxAfterSelectingSpot(Map<String, String> objDictionary,AndroidDriver androiddriver)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		try {Thread.sleep(2000);}catch (Exception e) {}
		String strCondition = ConditionalStepText(objDictionary,androiddriver, "Meter Payment", "Dialog Message", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			String strDialogMessage = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Dialog Message", 1, "strDialogMessage");
			if(strDialogMessage.contains("Parking expired"))
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Parking expired");}
			else if (strDialogMessage.contains("No rates that are matching for the current time"))
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"No rates that are matching for the current time");}
			else if (strDialogMessage.contains("Maximum time already purchased"))
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Maximum time already purchased");}
		}
	}
	public String AddTimeToExistingTime(String strTime, String strPlusMinutes,String strDateFormat)
	{
		String newTime = "";
		try
		{
			DateFormat sdf = new SimpleDateFormat(strDateFormat);
			Date startDate = sdf.parse(strTime);
			Calendar cal = Calendar.getInstance();
			cal.setTime(startDate);
			cal.add(Calendar.MINUTE, Integer.parseInt(strPlusMinutes));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e)
		{
			System.out.println("MIH");
		}
		return newTime;
	}
	public String SubtractTimeToExistingTime(String strTime, String strPlusMinutes,String strDateFormat)
	{
		String newTime = "";
		try
		{
			DateFormat sdf = new SimpleDateFormat(strDateFormat);
			Date startDate = sdf.parse(strTime);
			Calendar cal = Calendar.getInstance();
			cal.setTime(startDate);
			cal.add(Calendar.MINUTE, -Integer.parseInt(strPlusMinutes));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e) {}
		return newTime;
	}
	public String SENTRYMOBILE_CreateRandomLicensePlateNumber()
	{
//		String strAutomationUser = System.getProperty("user.name");
//		return strAutomationUser.substring(0, 6).toUpperCase();
		Random r = new Random();
	    String alphabet = "1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ";
	    String LicencePlateNumber = "";
	    for (int i = 0; i < 6; i++) {LicencePlateNumber = LicencePlateNumber + alphabet.charAt(r.nextInt(alphabet.length()));}
	    return LicencePlateNumber;
	}
	public String SENTRYMOBILE_ConvertMinutesToHrsAndMins(String strMinutes)
	{
		int intMinutes = Integer.parseInt(strMinutes);
		if (intMinutes > 60)
		{
			int hours = intMinutes / 60;
			int minutes = intMinutes % 60;
			if(minutes == 0)
			{strMinutes = Integer.toString(hours)+" Hrs";}
			else
			{strMinutes = Integer.toString(hours)+" Hrs "+Integer.toString(minutes)+ " Mins";}
		}
		else
		{strMinutes = strMinutes+ " Mins";}
		return strMinutes;
	}
	public String SENTRYMOBILE_ConvertMinutesToHrAndMins(String strMinutes)
	{
		int intMinutes = Integer.parseInt(strMinutes);
		if (intMinutes > 60)
		{
			int hours = intMinutes / 60;
			int minutes = intMinutes % 60;
			strMinutes = Integer.toString(hours)+" Hr "+Integer.toString(minutes)+ " Mins";
		}
		return strMinutes;
	}
	public void SENTRYMOBILE_ValidateParkingSessions(Map<String, String> objDictionary,AndroidDriver androiddriver, String strLicensePlateNumber)
    {
		CommonANDROID clsCommonMobile = new CommonANDROID();
		Meter clsMeter = new Meter();
		//Dictionary Variables
		String strHost = objDictionary.get("strHost");
		String strMeterSpotName = objDictionary.get("strMeterSpotName");
		//Spot:
		clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "testautof_touch_screen.py");
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Spot", 1, "Value", "Spot : "+strMeterSpotName);
		//License Plate Number
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "License Plate Number", 1, "Value", strLicensePlateNumber);
		//Validate Parked at
		String strParkingSessionsParkedAtTime = objDictionary.get("strParkingSessionsParkedAtTime");
		String strParkingSessionsParkedAtTimeMinusOne = objDictionary.get("strParkingSessionsParkedAtTimeMinusOne");
		String strParkingSessionsParkedAtTimePlusOne = objDictionary.get("strParkingSessionsParkedAtTimePlusOne");
		String strActualParkingSessionsParkedAtTime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Parked at", 1, "strActualParkingSessionsParkedAtTime");
		if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTime))
		{Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+ strParkingSessionsParkedAtTime+")"+"");}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimeMinusOne))
		{Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimeMinusOne+")"+"");}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimePlusOne))
		{Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimePlusOne+")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Parked at) with index (1) did not equal (Parked " + strParkingSessionsParkedAtTime + ") - actual value (" + strActualParkingSessionsParkedAtTime + ")");}
	    //Validate Parking Expires in
		String strMeterRemainingTimeSeconds = clsMeter.GetMeterRemainingTimeSeconds(objDictionary);
		int intMeterRemainingTimeMinutes = (int)Math.round(Double.parseDouble(strMeterRemainingTimeSeconds)/60);
		int intMeterRemainingTimeMinutesMinusOne = (int)Math.round(Double.parseDouble(strMeterRemainingTimeSeconds)/60) -1;
		String strMeterRemainingTimeMinutes = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterRemainingTimeMinutes));
		String strMeterRemainingTimeMinutesMinusOne = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterRemainingTimeMinutesMinusOne));
		String strActualParkingExpiresIn = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Parking Expires in", 1, "strActualParkingExpiresIn");
		if(strActualParkingExpiresIn.equals("Parking expires in "+strMeterRemainingTimeMinutes))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled (Parking expires in "+strMeterRemainingTimeMinutes+")");}
		else if(strActualParkingExpiresIn.equals("Parking expires in "+strMeterRemainingTimeMinutesMinusOne))
		{Reporter.log("The Text (Parking expires in) with index (1) equaled (Parking expires in "+strMeterRemainingTimeMinutesMinusOne+")");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Parking expires in) with index (1) did not equal (Parking expires in "+strMeterRemainingTimeMinutes+") - actual value (" + strActualParkingExpiresIn + ")");}
		//Valid until Time
		String strValidUntilMinutes = Integer.toString(intMeterRemainingTimeMinutes);
    	String strValidUntilMinutesMinusOne = Integer.toString(intMeterRemainingTimeMinutes -1);
    	String strValidUntilMinutesPlusOne = Integer.toString(intMeterRemainingTimeMinutes +1);
    	String strActualValueUntil = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Valid until", 1, "strActualValueUntil");
    	String strCurrentTime_hmma = new SimpleDateFormat("h:mm a").format(new Date());
    	String strValidUntilTime = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutes,"h:mm a").replace(":00","");
    	String strValidUntilTimeMinusOne = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutesMinusOne,"h:mm a").replace(":00","");
    	String strValidUntilTimePlusOne = clsCommonMobile.AddTimeToExistingTime(strCurrentTime_hmma, strValidUntilMinutesPlusOne,"h:mm a").replace(":00","");
    	if(strActualValueUntil.equals("Valid until : "+strValidUntilTime))
		{Reporter.log("The Text (Valid until) with index (1) equalled (Valid until : " + strValidUntilTime + ")"+"");}
		else if(strActualValueUntil.equals("Valid until : "+strValidUntilTimeMinusOne))
		{Reporter.log("The Text (Valid until) with index (1) equalled (Valid until : " + strValidUntilTimeMinusOne + ")"+"");}
		else if(strActualValueUntil.equals("Valid until : "+strValidUntilTimePlusOne))
		{Reporter.log("The Text (Valid until) with index (1) equalled (Valid until : " + strValidUntilTimePlusOne + ")"+"");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Valid until) with index (1) did not equal (" + strValidUntilTime + ") - actual value (" + strActualValueUntil + ")");}
    }
	public String SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee(Map<String, String> objDictionary,AndroidDriver androiddriver, String strTotalFee,String strSpotNumber)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		HttpConnections clsHttpConnections = new HttpConnections();
		//Get Fees At Time of Purchase
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strDeviceId = objDictionary.get("strDeviceId");
		String[] arrMeterSpots = strDeviceId.split("-");
		String strMeterSpotName = "";
		if(strSpotNumber.equals("1")){strMeterSpotName = arrMeterSpots[0];}else{strMeterSpotName = arrMeterSpots[1];}
  		//Check if Lot Screen Displays
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Parked in spot", 1, "Contains", strMeterSpotName);
		String strFirstPayment = objDictionary.get("strFirstPayment");
		if(strFirstPayment == null){strFirstPayment = "0";}
		String strParkingFee = strTotalFee;
		String strCurrentMeterTime = objDictionary.get("strCurrentMeterTime");if(strCurrentMeterTime == null){strCurrentMeterTime = "0";}
		if(strCurrentMeterTime.equals("0"))
		{
			double dblTotalFee = Double.parseDouble(strTotalFee.replace("$",""));
			double dblConvenienceFee = Double.parseDouble(strFirstPayment)*.01;
			double dblParkingFee = dblTotalFee - dblConvenienceFee;
			DecimalFormat dFormat = new DecimalFormat("$0.00");
			strParkingFee = dFormat.format(dblParkingFee);
			VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Parking Fee", 1, "Contains", dFormat.format(dblParkingFee));
			VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Total Fee", 1, "Contains", dFormat.format(dblTotalFee));
		}
		else
		{
			double dblTotalFee = Double.parseDouble(strTotalFee.replace("$",""));
			double dblConvenienceFee = Double.parseDouble(strFirstPayment)*.01;
			double dblParkingFee = dblTotalFee - dblConvenienceFee;
			DecimalFormat dFormat = new DecimalFormat("$0.00");
			strParkingFee = dFormat.format(dblParkingFee);
			VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Parking Fee", 1, "Contains", dFormat.format(dblParkingFee));
			VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Convenience Fee", 1, "Contains", dFormat.format(dblConvenienceFee));
			objDictionary.remove("strConveninceFee");objDictionary.put("strConveninceFee", dFormat.format(dblConvenienceFee));
			VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Total Fee", 1, "Contains", dFormat.format(dblTotalFee));
		}
		return strParkingFee;
	}
