	//Rate Initial Payment
	public void SENTRYMOBILE_MobilePaymentInitialPayment(Map<String, String> objDictionary, String strLicensePlateNumber, String strCreditCardIncrementTime, String strFreeTimeFirstPayment)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Classes
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Dictionary Variables
	  	String strVirtualMeter = objDictionary.get("strVirtualMeter");if(strVirtualMeter == null) {strVirtualMeter = "False";}
	  	String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
	  	//Open Sentry Mobile
		AndroidDriver androiddriver = clsCommonMobile.SENTRYMOBILE_NavigateToMeterPaymentPopulateSelectSpotAndLicensePlate(objDictionary, strLicensePlateNumber);
		String strTotalFee = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Meter Amount", 1, "strTotalFee");
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Purchase Parking", 1);
	 	clsCommonMobile.SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee(objDictionary, androiddriver, strTotalFee,"1");
	 	clsCommonMobile.CLICK_MeterPayment_YesPurchase(objDictionary, androiddriver, strLicensePlateNumber);
		//VMT: Validate Meter Time
	 	int intExpectedRemainingTimeMinutes = 0;
	 	if(strMinutesBeforeFreeStart != null)
	 	{
	 		intExpectedRemainingTimeMinutes = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null, strMinutesBeforeFreeStart, "0");
	 		//If Minutes Before Free is > Purchased Time Used Purchased Time
	 		if(intExpectedRemainingTimeMinutes > (Integer.parseInt(strCreditCardIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment)))
			{
	 			intExpectedRemainingTimeMinutes = Integer.parseInt(strCreditCardIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment);
			}
	 		//This Free Disconnect Off doesn't work
	 		String strFreeDisconnectValue = objDictionary.get("strFreeDisconnectValue"); if(strFreeDisconnectValue == null) {strFreeDisconnectValue = "On";}
	 		if(strFreeDisconnectValue.equals("Off"))
	 		{
	 			String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");
	 			intExpectedRemainingTimeMinutes =  Integer.parseInt(strCreditCardIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strFreeTimeMinutes);
	 		}
	 	}
	 	else
	 	{
	 		intExpectedRemainingTimeMinutes = Integer.parseInt(strCreditCardIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment);
	 	}
	 	clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null,  intExpectedRemainingTimeMinutes,"1");
	 	if (strVirtualMeter.equals("True")){clsMeter.SENTRYMETER_StoreParkingSessionTime(objDictionary);}
	 	//Validate Parked at time
	 	clsCommonMobile.SENTRYMOBILE_ValidateRateInitialPaymentParkingSessionValues(objDictionary, androiddriver, strLicensePlateNumber,"250",  strCreditCardIncrementTime, strFreeTimeFirstPayment);
	}
	public void SENTRYMOBILE_MobilePaymentInitialPaymentMaxTime(Map<String, String> objDictionary, AndroidDriver androiddriver, String strLicensePlateNumber, String strCreditCardIncrementTime)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Classes
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Dictionary Variables
	  	String strFreeDisconnectValue = objDictionary.get("strFreeDisconnectValue");
	  	if(strFreeDisconnectValue == null){strFreeDisconnectValue = "";}
		//Open Sentry Mobile
		clsCommonMobile.SENTRYMOBILE_Open(objDictionary, androiddriver);
		clsCommonMobile.SENTRYMOBILE_LoginOrRegisterWithRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver, "parker", strLicensePlateNumber, "Enroll later");
  		//Wait for GPS Map to Load
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
		try {Thread.sleep(2000);}catch (Exception e) {}
		clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
		clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, androiddriver, strLicensePlateNumber,  "Alabama");
		try {Thread.sleep(2000);}catch (Exception e) {}
		//SENTRYMOBILE_ValidateMaxMeterTime
		String strMeterMaxTime = clsMeter.GetMeterMaxTime(objDictionary, null,"1");
		int intTotalMaxTimeMin = Integer.parseInt(strMeterMaxTime);
		strMeterMaxTime = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intTotalMaxTimeMin));
		System.out.println("MeterMaxTime: "+strMeterMaxTime);
		int intTotalMaxTimeMinMinusOne = intTotalMaxTimeMin -1;
		//Store ActualMaxtime
		String strActualMaxtime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Max time", 1, "strActualMaxtime");
		//Convert Minutes to Hr Min
		String strTotalMaxTimeMin = "Max time : "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intTotalMaxTimeMin));
		String strTotalMaxTimeMinMinusOne = "Max time : "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intTotalMaxTimeMinMinusOne));
		//Validate ActualMaxtime to ExpectedMaxtime
		if(strActualMaxtime.contains(strTotalMaxTimeMin))
		{Reporter.log("The Text (Max time) with index (1) equaled (Max time :"+strTotalMaxTimeMin);}
		else if(strActualMaxtime.contains(strTotalMaxTimeMinMinusOne))
		{
			intTotalMaxTimeMin = intTotalMaxTimeMinMinusOne;
			Reporter.log("The Text (Max time) with index (1) equaled (Max time : "+strTotalMaxTimeMinMinusOne);
		}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Max time) with index (1) did not equal (Max time : " + strTotalMaxTimeMinMinusOne + ") - actual value (" + strActualMaxtime + ")");}
		//BMT: Buy Max Time
		clsCommonMobile.SENTRYMOBILE_BuyMaxTime(objDictionary, androiddriver, intTotalMaxTimeMin, strCreditCardIncrementTime,"1");
	}
	public void SENTRYMOBILE_ValidateRateInitialPaymentParkingSessionValues(Map<String, String> objDictionary, AndroidDriver androiddriver, String strLicensePlateNumber,String strMaximumDuration, String strMeterTimeIncrementValue,String strFreeTimeFirstPayment)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Classes
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		//Dictionary Variables
	  	String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
	  	String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart"); if(strMinutesBeforeFreeStart == null) {strMinutesBeforeFreeStart = "";}
	  	String strMinutesBeforeFreeParking = objDictionary.get("strMinutesBeforeFreeParking"); if(strMinutesBeforeFreeParking == null) {strMinutesBeforeFreeParking = "";}
	  	String strFirstPaymentTime = objDictionary.get("strFirstPaymentTime");
		//Calculate intMeterRemainingTime
        int intUsedTime = clsMeter.METER_CalculateUsedTime(objDictionary, null, strFirstPaymentTime);
	  	int intMeterRemainingTimeMinutes = 0;
  		if(strVirtualMeter.equals("True"))
  		{
  			if(strMinutesBeforeFreeStart.equals(""))
  			{
  				intMeterRemainingTimeMinutes = Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue) - intUsedTime;
  			}
  			else
  			{
  				String strFreeDisconnectValue = objDictionary.get("strFreeDisconnectValue"); if(strFreeDisconnectValue == null) {strFreeDisconnectValue = "On";}
  		 		if(strFreeDisconnectValue.equals("Off"))
  		 		{
  		 			String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");
  		 			intMeterRemainingTimeMinutes =  Integer.parseInt(strMeterTimeIncrementValue) + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strFreeTimeMinutes);
  		 		}
  		 		else
  		 		{intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null,strMinutesBeforeFreeStart);}
  			}
  		}
  		else
  		{
  			if(strMinutesBeforeFreeStart.equals(""))
  			{intMeterRemainingTimeMinutes = Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue) - intUsedTime;}
  			else
  			{
  				//This no longer works
  				String strFreeDisconnectValue = objDictionary.get("strFreeDisconnectValue"); if(strFreeDisconnectValue == null) {strFreeDisconnectValue = "On";}
  		 		if(strFreeDisconnectValue.equals("Off"))
  		 		{
  		 			String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");
  		 			intMeterRemainingTimeMinutes =  Integer.parseInt(strMeterTimeIncrementValue) + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strFreeTimeMinutes);
  		 		}
  		 		else
  		 		{
	  				intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null,strMinutesBeforeFreeStart) -1;
	  				if(intMeterRemainingTimeMinutes > Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue))
	  				{intMeterRemainingTimeMinutes = Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterTimeIncrementValue);}
  		 		}

  			}
  		}
  		//Validate SpotAndLicensePlateNumber
	  	clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary,androiddriver,strLicensePlateNumber);
		//Validate Parked at
	  	clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//ValidateParkingSessionsValidUntil
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsParkingExipresIn(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//Calculate Receipt Data
		double dblMeterTimeIncrementValue = Double.parseDouble(strMeterTimeIncrementValue);
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		//CalculateFees
		String strFirstPaymentFees = clsCommonWeb.SENTRYLINK_CalculateFirstPaymentFee(objDictionary);
		String strAmountPaid1 = clsCommonWeb.SENTRYLINK_CalculateCreditCardAmount(dblMeterTimeIncrementValue, strMeterTimeIncrementValue,dFormat);
		Double dblTotalAmountPaid = Double.parseDouble(strFirstPaymentFees.replace("$","")) + Double.parseDouble(strAmountPaid1.replace("$",""));
		int intTimePurchase1 = 0;
		if(strMinutesBeforeFreeStart.equals("")){intTimePurchase1 = Integer.parseInt(strMeterTimeIncrementValue) + Integer.parseInt(strFreeTimeFirstPayment);}
		else
		{
		 	//CalculateRemainingMinutesBeforeFree
		    int intRemaingMinutesBeforeFree = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null,strMinutesBeforeFreeStart);
		    if(intRemaingMinutesBeforeFree > Integer.parseInt(strMeterTimeIncrementValue) + Integer.parseInt(strFreeTimeFirstPayment))
		    {
		    		intRemaingMinutesBeforeFree = Integer.parseInt(strMeterTimeIncrementValue) + Integer.parseInt(strFreeTimeFirstPayment);
		    }
		    intTimePurchase1 = intRemaingMinutesBeforeFree;
		}
		//if(intMeterRemainingTimeMinutes<intTimePurchase1){intTimePurchase1 = intMeterRemainingTimeMinutes;}
		String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
		if(strConditional.equals("False")){clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);try {Thread.sleep(1500);}catch (Exception e) {}}
		DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
		String strPurchaseAt = dateFormat.format(date);
		//Validate Receipt
		clsCommonMobile.GlobalWait(objDictionary, androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Amount Paid", 15);
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblTotalAmountPaid)+" (Conv. fee "+strFirstPaymentFees+")");
    	clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Time purchased", 10);
  		String strTimePurchased = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurchased");
  		int intTimePurchase1PlusTwo = intTimePurchase1 +2;
  		int intTimePurchase1PlusOne = intTimePurchase1 +1;
    	int intTimePurchase1MinusOne = intTimePurchase1 -1;
    	if(strTimePurchased.contains(intTimePurchase1PlusTwo+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1PlusTwo+" Minutes)");}
    	else if(strTimePurchased.contains(intTimePurchase1PlusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1PlusOne+" Minutes)");}
    	else if(strTimePurchased.contains(intTimePurchase1+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1+" Minutes)");}
		else if(strTimePurchased.contains(intTimePurchase1MinusOne+" Minutes"))
		{Reporter.log("The Time purchased contained ("+intTimePurchase1MinusOne+" Minutes)");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Time purchased did not contain ("+intTimePurchase1+") - actual value ("+strTimePurchased+")");}
		try {Thread.sleep(1500);}catch (Exception e) {}
    	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "Contains", strPurchaseAt);
		androiddriver.quit();
	}
	//Rate Buy More Time
	public void SENTRYMOBILE_MobilePaymentBuyMoreTime(Map<String, String> objDictionary, String strLicensePlateNumber,String strMaximumDuration, String strCreditCardIncrementTime,String strFreeTimeFirstPayment,String strFirstPaymentType) throws Exception
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		HttpConnections clsHttpConnections = new HttpConnections();
		//Dictionary Variables
		AndroidDriver androiddriver = clsCommonMobile.SetMobileDriver(objDictionary, "SentryMobile","True","Parker");
  		clsCommonMobile.SENTRYMOBILE_Open(objDictionary, androiddriver);
  		clsCommonMobile.SENTRYMOBILE_LoginOrRegisterWithRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver, "parker",strLicensePlateNumber, "Enroll later");
		//Navigate to Meter Payment
		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
		clsCommonMobile.SENTRYMOBILE_PopulateOrValidateMeterPaymentMunicipality(objDictionary, androiddriver, "True");
		clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
		int intRemainingMaximumDuration;
		if(strFirstPaymentType.equals("Credit Card"))
		{
			intRemainingMaximumDuration = Integer.parseInt(strCreditCardIncrementTime) * 4;
		}
		else
		{
			intRemainingMaximumDuration =  Integer.parseInt(strCreditCardIncrementTime);
		}
		clsCommonMobile.SENTRYMOBILE_ValidateRateBuyMoreTimeMeterPaymentValues(objDictionary, androiddriver, strFreeTimeFirstPayment, strCreditCardIncrementTime,intRemainingMaximumDuration);
		clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, androiddriver, strLicensePlateNumber, "Alabama");
	 	clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Meter Payment", "{TextExists} Meter Payment~Meter Amount", 60);
  		String strTotalFee = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Meter Amount", 1, "strTotalFee");
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Purchase Parking", 1);
		clsCommonMobile.SENTRYMOBILE_ValidateSubsequentPaymentDialogAndReturnParkingFee(objDictionary, androiddriver, strTotalFee);
		//Click Yes Purchase
		clsCommonMobile.CLICK_MeterPayment_YesPurchase(objDictionary, androiddriver, strLicensePlateNumber);
		//Copy Parking Session results to results
		try {clsHttpConnections.ReportJsonParkingSessionInformation(objDictionary);}catch (Exception e) {}
		clsCommonMobile.SENTRYMOBILE_ValidateRateBuyMoreTimeParkingSessionValues(objDictionary, androiddriver, strLicensePlateNumber, Integer.parseInt(strCreditCardIncrementTime), strCreditCardIncrementTime, strFreeTimeFirstPayment,strFirstPaymentType);
	}
