	public void SENTRYMOBILE_ValidateRateBuyMoreTimeParkingSessionValues(Map<String, String> objDictionary, AndroidDriver androiddriver,String strLicensePlateNumber, int intMeterTimeIncrementValue, String strMeterTimeIncrementValue, String strFreeTimeFirstPayment, String strFirstPaymentType)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
	 	Meter clsMeter = new Meter();
		//Dictionary Variables
  		String strFirstPaymentTime = objDictionary.get("strFirstPaymentTime");
  		String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
  		String strMeterReboot = objDictionary.get("strMeterReboot");if(strMeterReboot == null) {strMeterReboot = "False";}
  		String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
		//Validate Spot and License Plate
		clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary, androiddriver, strLicensePlateNumber);
		//Validate Parked at
		clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//ValidateParkingSessionsValidUntil
		int intTotalMinutes = 0;
		int intUsedTimeBetweenPayments = 0;
		if(strFirstPaymentType.equals("Credit Card"))
		{
			if(strMeterReboot.equals("False"))
			{
				intTotalMinutes = Integer.parseInt(strMeterTimeIncrementValue) * 5 + Integer.parseInt(strFreeTimeFirstPayment);
			}
			else
			{
				intTotalMinutes = Integer.parseInt(strMeterTimeIncrementValue) * 5 + Integer.parseInt(strFreeTimeFirstPayment) + 5;
			}
		}
		else
		{
			if(strMinutesBeforeFreeStart != null)
			{
				intTotalMinutes = intMeterTimeIncrementValue + Integer.parseInt(strMeterTimeIncrementValue);
			}
			else
			{	
				if(strFirstPaymentType.equals("Credit Card"))
				{
					intTotalMinutes = Integer.parseInt(strMeterTimeIncrementValue) * 4 + Integer.parseInt(strFreeTimeFirstPayment);
				}
				else
				{
					intTotalMinutes = Integer.parseInt(strMeterTimeIncrementValue) * 2 + Integer.parseInt(strFreeTimeFirstPayment);
				}
			}
		}
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,intTotalMinutes);
		//Calculate intMeterRemainingTime
		int intUsedTime = clsMeter.METER_CalculateUsedTime(objDictionary, null, strFirstPaymentTime);
		int intMeterRemainingTimeMinutes = 0;
		intMeterRemainingTimeMinutes = intTotalMinutes - intUsedTime;
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsParkingExipresIn(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//Validate Receipt
		String strAmountPaid1 = "0";	String strAmountPaid2 = "$0.25";
	   	DecimalFormat dFormat = new DecimalFormat("$0.00");
	   	//Calculate Receipt Values
	   	if(strVirtualMeter.equals("False"))
	   	{
		   	//Get Meter Remaining Time
		   	String strMeterValidTimeRemaining = clsMeter.GetMeterValidTimeRemaining(objDictionary, null, "1");
	   	}
	   	int intFirstPaymentMinutes = 0;
	    if(strFirstPaymentType.equals("Coin"))
	    {
	    	strAmountPaid1 = "$0.25";
	    	intFirstPaymentMinutes = Integer.parseInt(strMeterTimeIncrementValue);
	    }
	    if(strFirstPaymentType.equals("Credit Card"))
    	{
    		strAmountPaid1 = "$1.00";
    		intFirstPaymentMinutes = Integer.parseInt(strMeterTimeIncrementValue) * 4;
    	}
    	else if(strFirstPaymentType.equals("Mobile"))
    	{
    		strAmountPaid1 = "$0.25";
    		String strFirstPayment = objDictionary.get("strFirstPayment");
    		if (strFirstPayment != null){double dblFirstPayment = .25 + Integer.parseInt(strFirstPayment)*.01;strAmountPaid1 = dFormat.format(dblFirstPayment);}
    		intFirstPaymentMinutes = Integer.parseInt(strMeterTimeIncrementValue);
    	}
	    intFirstPaymentMinutes = Integer.parseInt(strFreeTimeFirstPayment) + intFirstPaymentMinutes;
	    //Subsequent Payment
	    String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
		if (strSubsequentPayment != null)
		{
			double dblSubsequentPayment = .25 + Integer.parseInt(strSubsequentPayment)*.01;
			strAmountPaid2 = dFormat.format(dblSubsequentPayment);
		}
		//strMobielTimePurchased gets added in the function: SENTRYMOBILE_ValidateRateBuyMoreTimeMeterPaymentValues
		String strMobileTimePurchased = objDictionary.get("strMobileTimePurchased");
    	int intSecondPaymentMinutes = Integer.parseInt(strMobileTimePurchased);
    	if(strMinutesBeforeFreeStart != null)
		{
    			intSecondPaymentMinutes = intSecondPaymentMinutes - intUsedTimeBetweenPayments;
		}
		//Validate Receipt	
    	TakeAndroidScreenShot(androiddriver,objDictionary,"");
    	String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
	    if(strConditional.equals("False"))	{clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);try {Thread.sleep(1500);}catch (Exception e) {}}
	    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
		String strPurchaseAt = dateFormat.format(date);
		//First Payment
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 2, "Contains", strAmountPaid1);
		//MobileElement objFrame = androiddriver.findElement(By.xpath(".//android.widget.FrameLayout/android.widget.LinearLayout/android.widget.FrameLayout/android.view.ViewGroup/android.widget.FrameLayout[2]/android.widget.RelativeLayout/android.support.v4.view.ViewPager/android.widget.RelativeLayout/android.widget.ExpandableListView/android.widget.RelativeLayout"));
		WebElement objFrame = androiddriver.findElement(By.xpath(".//android.widget.LinearLayout/android.widget.FrameLayout/android.view.ViewGroup/android.widget.FrameLayout[2]/android.widget.RelativeLayout/androidx.viewpager.widget.ViewPager/android.widget.RelativeLayout/android.widget.ExpandableListView"));
		ElementSwipe  clsElementSwipe  = new ElementSwipe();
		clsElementSwipe.Swipe(androiddriver,objFrame,"SWIPE_UP"); 
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 2, "Contains", strPurchaseAt);		
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 2, "Contains", intFirstPaymentMinutes+" Minutes");
		//2nd Payment  
		try {Thread.sleep(2000);}catch (Exception e) {}
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", strAmountPaid2);
	    clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "Contains", strPurchaseAt);
	    try {Thread.sleep(2000);}catch (Exception e) {}
	    clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "Contains", intSecondPaymentMinutes+" Minutes");

	    
	    
//  		This code might need to be setup for the 2nd payment it changed when they changed the order of the receipts
//  		String strTimePurchased = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurchased");
//  		int intFirstPaymentMinutesMinus1 = intFirstPaymentMinutes -1;
//  		int intFirstPaymentMinutesPlus1 = intFirstPaymentMinutes +1;
//  		if(strTimePurchased.contains(intFirstPaymentMinutes+" Minutes"))
//  		{Reporter.log("The Time purchased contained ("+intFirstPaymentMinutesPlus1+" Minutes)");}
//  		else if(strTimePurchased.contains(intFirstPaymentMinutes+" Minutes"))
//  		{Reporter.log("The Time purchased contained ("+intFirstPaymentMinutes+" Minutes)");}
//  		else if(strTimePurchased.contains(intFirstPaymentMinutesMinus1+" Minutes"))
//  		{Reporter.log("The Time purchased contained ("+intFirstPaymentMinutesMinus1+" Minutes)");}
//  		else 
//  		{
//  			clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Time purchased did not contain ("+intFirstPaymentMinutes+") - actual value ("+strTimePurchased+")");
//  		}
	    
	    androiddriver.quit();
    }
	//Buy Remaining Time
	public void SENTRYMOBILE_PurchaseRemainingTime(Map<String, String> objDictionary,String strLicensePlateNumber, String strCreditCardIncrementTime, String strMaximumDuration, String strMeterTimeIncrementValue, String strFreeTimeFirstPayment, String strPreviousPurchasedTime)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Classes
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Open Sentry Mobile
	  	AndroidDriver androiddriver = clsCommonMobile.SetMobileDriver(objDictionary, "SentryMobile","True","Parker");
		clsCommonMobile.SENTRYMOBILE_Open(objDictionary, androiddriver);
		clsCommonMobile.SENTRYMOBILE_LoginOrRegisterWithRememberMeOffEmailIdWithoutCaps(objDictionary, androiddriver, "parker",strLicensePlateNumber, "Enroll later");
		//Navigate to MeterPayment
		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Meter Payment");
		try {Thread.sleep(2000);}catch (Exception e) {}
		clsCommonMobile.Populate_MeterPayment_SelectSpot(objDictionary,androiddriver,"1");
		clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, androiddriver, strLicensePlateNumber,  "Alabama");
		try {Thread.sleep(4000);}catch (Exception e) {}
		//ValidateMeterPaymentMaxTime
		int intTotalMaxTimeMin = clsCommonMobile.SENTRYMOBILE_ValidateMeterPaymentMaxTime(objDictionary,androiddriver,0);
		//PRT: Purchase Remaining Time - Removed because Max time cal changed
		clsCommonMobile.SENTRYMOBILE_PurchaseRemainingTime(objDictionary, androiddriver, intTotalMaxTimeMin, strCreditCardIncrementTime);
		//Purchase Time
		clsCommonMobile.CLICK_MeterPayment_YesPurchase(objDictionary, androiddriver, strLicensePlateNumber);
		//ValidateParkingSessionValues_PurchaseRemainingTime
		clsCommonMobile.SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues(objDictionary, androiddriver, strLicensePlateNumber, strMaximumDuration, strMeterTimeIncrementValue, strFreeTimeFirstPayment,strPreviousPurchasedTime);
	}
	public void SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues(Map<String, String> objDictionary, AndroidDriver androiddriver,String strLicensePlateNumber, String strMaximumDuration, String strMeterTimeIncrementValue, String strFreeTimeFirstPayment, String strPreviousPurchasedTime)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		CommonWeb clsCommonWeb = new CommonWeb();
		String strHost = objDictionary.get("strHost");
		clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,strHost, "testautof_touch_screen.py");
		//Validate Spot and License Plate
		clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary, androiddriver, strLicensePlateNumber);
		//ValidateParkingSessionsParkedAt
		clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//ValidateParkingSessionsValidUntil
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,Integer.parseInt(strMaximumDuration));
		//CalculateMeterRemainingTimeMinutes
		int intMeterRemainingTimeMinutes = clsCommonMobile.SENTRYMOBILE_ParkingSessionsCalculateMeterRemainingTimeMinutes(objDictionary,strMaximumDuration);
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsParkingExipresIn(objDictionary,androiddriver,intMeterRemainingTimeMinutes);
		//Calculate Receipt DataclsCommonWeb
		//double dblMeterTimeIncrementValue = Double.parseDouble(strMeterTimeIncrementValue);
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		double dblDuration = Double.parseDouble(strMaximumDuration)-Double.parseDouble(strPreviousPurchasedTime)-Double.parseDouble(strFreeTimeFirstPayment);
		String strAmountPaid1 = clsCommonWeb.SENTRYLINK_CalculateCreditCardAmount(dblDuration, strMeterTimeIncrementValue, dFormat);
		int intTimePurchase2  = 0;
		if(!strPreviousPurchasedTime.equals("0"))
		{intTimePurchase2 = Integer.parseInt(strMaximumDuration) - Integer.parseInt(strPreviousPurchasedTime)- Integer.parseInt(strFreeTimeFirstPayment);}
		else
		{intTimePurchase2 = Integer.parseInt(strMaximumDuration) - Integer.parseInt(strPreviousPurchasedTime);}
		int intTimePurchase1 = Integer.parseInt(strPreviousPurchasedTime) + Integer.parseInt(strFreeTimeFirstPayment);
		DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
		String strPurchaseAt = dateFormat.format(date);
		String strTotalFee = objDictionary.get("strTotalFee");				
		String strAmountPaid2 = clsCommonWeb.SENTRYLINK_CalculateCreditCardAmount(Double.parseDouble(strPreviousPurchasedTime), strMeterTimeIncrementValue,dFormat);
		String strFirstPaymentFees = "$0.00";
		String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
		if(strConditional.equals("False"))
		{
			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);
			try {Thread.sleep(1500);}catch (Exception e) {}
		}
		String strSubsequentPaymentFees = clsCommonWeb.SENTRYLINK_CalculateSubsequentPaymentFee(objDictionary);
		if(strTotalFee == null)
		{
			//Second Payment
			double dblSubsequentTotalPayment = Double.parseDouble(strAmountPaid1.replace("$","")) + Double.parseDouble(strSubsequentPaymentFees.replace("$",""));
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", dFormat.format(dblSubsequentTotalPayment)+" (Conv. fee "+strSubsequentPaymentFees+")");
		}
		else
		{
			String strConvFee = "";
			if(strPreviousPurchasedTime.equals("0"))
			{
				strConvFee = objDictionary.get("strFirstTimePaymentFee");
			}
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", strTotalFee+" (Conv. fee "+strConvFee+")");
		}
		int intTimePurchase1Minus2 = intTimePurchase2 - 1;
		//Validate Time Purchase 2nd Payment
		String strTimePurhase2Payment = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurhase2Payment");
		if(strTimePurhase2Payment.contains(Integer.toString(intTimePurchase2)))
		{Reporter.log("The Text (Time purchased) with index (1) contained (" + intTimePurchase2 + ")");}
		else if(strTimePurhase2Payment.contains(Integer.toString(intTimePurchase1Minus2)))
		{Reporter.log("The Text (Time purchased) with index (1) contained (" + intTimePurchase1Minus2 + ")");}
		else
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Time purchased) with index (1) did not contain (" + intTimePurchase2 + ") - actual value (" + strTimePurhase2Payment + ")");}
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "Contains", strPurchaseAt);
		if(!strPreviousPurchasedTime.equals("0"))
		{
			//First Payment
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", strAmountPaid1 +" (Conv. fee "+strFirstPaymentFees+")");
			//Scroll Up
			WebElement objFrame = androiddriver.findElement(By.xpath(".//android.widget.LinearLayout/android.widget.FrameLayout/android.view.ViewGroup/android.widget.FrameLayout[2]/android.widget.RelativeLayout/androidx.viewpager.widget.ViewPager/android.widget.RelativeLayout/android.widget.ExpandableListView"));
			ElementSwipe  clsElementSwipe  = new ElementSwipe();
			clsElementSwipe.Swipe(androiddriver,objFrame,"SWIPE_UP");
			//Validate Time Purchase 1st Payment
			int strTimePurhase2PaymentPlus1 = intTimePurchase2 + 1;
			int strTimePurhase2PaymentPlus2 = intTimePurchase2 + 2;
			int strTimePurhase2PaymentPlus3 = intTimePurchase2 + 3;
			String strTimePurhase1Payment = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "strTimePurhase1Payment");
			if(strTimePurhase1Payment.contains(Integer.toString(intTimePurchase2)))
			{Reporter.log("The Text (Time purchased) with index (1) contained (" + intTimePurchase2 + ")");}
			else if(strTimePurhase1Payment.contains(Integer.toString(strTimePurhase2PaymentPlus1)))
			{Reporter.log("The Text (Time purchased) with index (1) contained (" + strTimePurhase2PaymentPlus1 + ")");}
			else if(strTimePurhase1Payment.contains(Integer.toString(strTimePurhase2PaymentPlus2)))
			{Reporter.log("The Text (Time purchased) with index (1) contained (" + strTimePurhase2PaymentPlus2 + ")");}
			else if(strTimePurhase1Payment.contains(Integer.toString(strTimePurhase2PaymentPlus3)))
			{Reporter.log("The Text (Time purchased) with index (1) contained (" + strTimePurhase2PaymentPlus3 + ")");}
			else
			{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Time purchased) with index (1) did not contain (" + intTimePurchase2 + ") - actual value (" + strTimePurhase1Payment + ")");}
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 2, "Contains", strPurchaseAt);
			androiddriver.quit();
		}
	}
	//Rate Purchase Max Time
	public String SENTRYMOBILE_BuyMaxTime(Map<String, String> objDictionary,AndroidDriver androiddriver, int intTotalMaxTimeMin, String strMeterIncrementTime,String strPaymentNbr)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
    	CommonANDROID clsCommonMobile = new CommonANDROID();
    	Meter clsMeter = new Meter();
    	HttpConnections clsHttpConnections = new HttpConnections();
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Buy Max Time", 1);
		//Validate Total Amount
		String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
		String strSecondRateStartTime = objDictionary.get("strSecondRateStartTime");
		DecimalFormat dFormat = new DecimalFormat("#0.00");
		//Check For Fees
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strTotalFee = "0";
		if(strPaymentNbr.equals("1"))
		{
			String strFirstPayment = objDictionary.get("strFirstPayment");
			//intTotalMaxTimeMin = (int)Math.ceil(intTotalMaxTimeMin/Double.parseDouble(strMeterIncrementTime)) * Integer.parseInt(strMeterIncrementTime);
			if (strFirstPayment != null)
			{
				if(strSecondRateStartTime != null)
				{
					int intRemainingMinutesInFirstRateSet = clsMeter.METER_CalculateRemainingMinutesBeforeNextRate(objDictionary, null, strSecondRateStartTime)-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes First Rateblock: "+intRemainingMinutesInFirstRateSet);
					int intNumberOfPaymentInFirsttRateSet = intRemainingMinutesInFirstRateSet/12;
					int intRemainingMinutes = intRemainingMinutesInFirstRateSet - intNumberOfPaymentInFirsttRateSet * 12;
					Reporter.log("intRemainingMinutes: "+intRemainingMinutes);
					String strTotalFeeFirstRateSet = "$" + dFormat.format((int)Math.ceil(((double)intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime)) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 1st Rate Block Equaled: "+strTotalFeeFirstRateSet);
					int intMinutesInSecondRateSet = intTotalMaxTimeMin - intRemainingMinutesInFirstRateSet-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes Second Rateblock: "+intMinutesInSecondRateSet);
					String strTotalFeeSecondRateSet = "$" + dFormat.format((int)Math.ceil(((double)intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 2nd Rate Block Equaled: "+strTotalFeeSecondRateSet);
					String strFirstTimePaymentFee = "$" + dFormat.format((Integer.parseInt(strFirstPayment)*.01));
					Reporter.log("First Payment Fee: "+strFirstTimePaymentFee);
					objDictionary.put("strFirstTimePaymentFee",strFirstTimePaymentFee);//Used SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues
					strTotalFee = "$" + dFormat.format((int)Math.ceil(((double)intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime)) * (Double.parseDouble(strMeterNextRateCost)/100) + (int)Math.ceil(((double)intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100) + Integer.parseInt(strFirstPayment)*.01);
				}
				else
				{
					strTotalFee = "$" + dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)+ (Integer.parseInt(strFirstPayment)*.01));
				}
			}
			else
			{
				if(strSecondRateStartTime != null)
				{
					int intRemainingMinutesInFirstRateSet = clsMeter.METER_CalculateRemainingMinutesBeforeNextRate(objDictionary, null, strSecondRateStartTime)-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes First Rateblock: "+intRemainingMinutesInFirstRateSet);
					int intMinutesInSecondRateSet = intTotalMaxTimeMin - intRemainingMinutesInFirstRateSet;
					Reporter.log("Remaining Minutes Second Rateblock: "+intMinutesInSecondRateSet);

					String strTotalFeeFirstRateSet = "$" + dFormat.format((intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 1st Rate Block Equaled: "+strTotalFeeFirstRateSet);

					String strTotalFeeSecondRateSet = "$" + dFormat.format((intMinutesInSecondRateSet)/ 10 * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 2nd Rate Block Equaled: "+strTotalFeeSecondRateSet);
					strTotalFee = "$" + dFormat.format(((intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime) + (intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100));
				}
				else
				{
					strTotalFee = "$" + dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100));
				}
			}
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Total Fee", 1, "Contains", strTotalFee);
		}
		else
		{
			String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
			intTotalMaxTimeMin = (int)Math.ceil(intTotalMaxTimeMin/Double.parseDouble(strMeterIncrementTime)) * Integer.parseInt(strMeterIncrementTime);
			if (strSubsequentPayment != null)
			{strTotalFee = "$" + dFormat.format(intTotalMaxTimeMin / Integer.parseInt(strMeterIncrementTime) * Integer.parseInt(strMeterNextRateCost)/100 + (Integer.parseInt(strSubsequentPayment)*.01));}
			else
			{
				strTotalFee = "$" + dFormat.format(intTotalMaxTimeMin / Double.parseDouble(strMeterIncrementTime) * Double.parseDouble(strMeterNextRateCost)/100);
			}
			clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Total Fee", 1, "Contains", strTotalFee);
		}
		objDictionary.put("strTotalFee",strTotalFee);//Used SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues
		return strTotalFee;
	}
	//Purchase Remaining Time
	public String SENTRYMOBILE_PurchaseRemainingTime(Map<String, String> objDictionary,AndroidDriver androiddriver, int intRemainingMaxTime, String strCreditCardIncrementTime)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID clsCommonMobile = new CommonANDROID();
		Meter clsMeter = new Meter();
		HttpConnections clsHttpConnections = new HttpConnections();
		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Meter Payment", "Buy Max Time", 1);
		//Validate Purchase Time
		String strDialogPurchaseTime = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intRemainingMaxTime));
		int intRemainingMaxTimeMinusOne = intRemainingMaxTime - 1;
		String strDialogPurchaseTimeMinusOne = clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intRemainingMaxTimeMinusOne));
		String strPurchaseTime = clsCommonMobile.StoreText(objDictionary, androiddriver,  "Meter Payment", "Purchase Time", 1, "strPurchaseTime");
		if(strPurchaseTime.contains(strDialogPurchaseTime))
		{Reporter.log("The Text (Purchase Time) with index (1) contained (" + strDialogPurchaseTime + ")");}
		else if(strPurchaseTime.contains(strDialogPurchaseTimeMinusOne))
		{Reporter.log("The Text (Purchase Time) with index (1) contained (" + strDialogPurchaseTimeMinusOne + ")-Minus 1");}
		else
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Purchase Time) with index (1) did not contain (" + strDialogPurchaseTime + ") - actual value (" + strPurchaseTime + ")");}
		//Validate Total Amount
		String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
		DecimalFormat dFormat = new DecimalFormat("#0.00");
		//Check For Fees
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
		String strTotalFee = "0";
		//Calculate Total Fees
		if (strSubsequentPayment != null)
		{strTotalFee = "$" + dFormat.format(intRemainingMaxTime / Double.parseDouble(strCreditCardIncrementTime) * Double.parseDouble(strMeterNextRateCost)/100 + (Double.parseDouble(strSubsequentPayment)*.01));}
		else
		{strTotalFee = "$" + dFormat.format((intRemainingMaxTime / Double.parseDouble(strCreditCardIncrementTime)) * Double.parseDouble(strMeterNextRateCost)/100);}
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Meter Payment", "Total Fee", 1, "Contains", strTotalFee);
		return strTotalFee;
	}
