	//Parking Session Page
	public int SENTRYMOBILE_ParkingSessionsCalculateMeterRemainingTimeMinutes(Map<String, String> objDictionary,String strMaximumDuration)
	{
		Meter clsMeter = new Meter();
		String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
		int intMeterRemainingTimeMinutes = 0;
		if (strVirtualMeter.equals("True"))
		{
			String strMinutesBeforeFreeParking = objDictionary.get("strMinutesBeforeFreeParking");
			intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null,strMinutesBeforeFreeParking);
		}
		else
		{
			String strMeterRemainingTimeSeconds = clsMeter.GetMeterRemainingTimeSeconds(objDictionary);
			double dblMeterRemainingTimeSeconds = Double.parseDouble(strMeterRemainingTimeSeconds);
			double dblMeterRemainingTimeMinutes = dblMeterRemainingTimeSeconds/60;
			intMeterRemainingTimeMinutes = (int)Math.round(dblMeterRemainingTimeMinutes);
		}
		return intMeterRemainingTimeMinutes;
	}

