	//Common Calculations
	public int CALCULATIONS_MeterPayment_CalculateRemainingFreeTime(Map<String, String> objDictionary,AndroidDriver androiddriver)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strFreeParkingEndTime12 = objDictionary.get("strFreeParkingEndTime12");//.replace(":00","");
		String strCurrentTime_hmma = new SimpleDateFormat("h:mm a").format(new Date());
		int intRemainingFreeTime = 0;
		SimpleDateFormat formater=new SimpleDateFormat("h:mm a");
		try
		{
			long d1=formater.parse(strFreeParkingEndTime12).getTime();
		    	long d2=formater.parse(strCurrentTime_hmma).getTime();
		    	long lUsedFreeSeconds = TimeUnit.MILLISECONDS.toSeconds(d1-d2);
		    	intRemainingFreeTime = (int) Math.round(lUsedFreeSeconds / 60.00);
		    Reporter.log("The value ("+intRemainingFreeTime+") intRemainingFreeMinutes");
	    	}catch (Exception e)
		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"Unable to Calculate Remaining Free Time-"+strMethodName);}
		return intRemainingFreeTime;
	}

