	public void VALIDATIONS_MeterPayment_ValidUntilTime(Map<String, String> objDictionary,AndroidDriver androiddriver, int intExistingPurchasedTime, String strFreeTimeFirstPayment)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		Meter clsMeter = new Meter();
		String strVirtualMeter = objDictionary.get("strVirtualMeter"); if(strVirtualMeter == null) {strVirtualMeter = "False";}
		String strFirstPaymentTime = objDictionary.get("strFirstPaymentTime");
		String strParkingSessionsParkedAtTime = objDictionary.get("strParkingSessionsParkedAtTime");
		if (strParkingSessionsParkedAtTime != null)
		{
			strParkingSessionsParkedAtTime = strParkingSessionsParkedAtTime.replace("Today at ","");
		}
		else
		{
			if(strFirstPaymentTime != null)
			{
				SimpleDateFormat sdf1 = new SimpleDateFormat("HH:mm:ss");
			    SimpleDateFormat sdf2 = new SimpleDateFormat("h:mm a");
			    try
			    {
			    		Date date = sdf1.parse(strFirstPaymentTime);
			    		System.out.println(sdf2.format(date));
			    		strParkingSessionsParkedAtTime = sdf2.format(date);
			    		Reporter.log("strCurrentTime_hmma ("+strParkingSessionsParkedAtTime+")-With strFirstPaymentTime");
			    }catch (Exception e)  {System.out.println("MIH");}
			}
			else
			{
				//This Should Parked At Time
				strParkingSessionsParkedAtTime = objDictionary.get("strSelectSpotTime");
			}
		}
		//Purchase Time
		String strMobileTimePurchased = clsCommonMobile.StoreTextField(objDictionary, androiddriver, "Meter Payment", "Purchase Time", 1, "strMobileTimePurchased");
		//Convert Mobile Time To Minutes
		if (strMobileTimePurchased.contains("Hrs"))
		{
			int intMobileTimePurchased = Integer.parseInt(strMobileTimePurchased.replaceAll("[^0-9.]", "")) * 60;
	    	strMobileTimePurchased = Integer.toString(intMobileTimePurchased);
	    }
		objDictionary.remove("strMobileTimePurchased");objDictionary.put("strMobileTimePurchased", strMobileTimePurchased.replaceAll("[^0-9.]", ""));
		String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes"); if(strFreeTimeMinutes == null) {strFreeTimeMinutes = "0";}
		int intRemainingFreeTime = 0;
		int intCurrentPurchaseTime = 0;
		if(strFirstPaymentTime == null)
		{
			intCurrentPurchaseTime = intRemainingFreeTime + Integer.parseInt(strMobileTimePurchased.replaceAll("[^0-9.]", ""));
			objDictionary.put("strFreeTimeAtFirstPayment",Integer.toString(intRemainingFreeTime));
		}
		else
		{
			String strFreeTimeAtFirstPayment = objDictionary.get("strFreeTimeAtFirstPayment");if(strFreeTimeAtFirstPayment == null) {strFreeTimeAtFirstPayment = "0";}
			intCurrentPurchaseTime =  Integer.parseInt(strFreeTimeAtFirstPayment)  +  Integer.parseInt(strMobileTimePurchased.replaceAll("[^0-9.]", ""));
			intExistingPurchasedTime = intExistingPurchasedTime + Integer.parseInt(strFreeTimeFirstPayment);
		}
		Reporter.log("The value ("+intExistingPurchasedTime+") intExistingPurchasedTime");
		if(strFreeTimeMinutes != "0")
		{
			int intValidUntilMinutes = intCurrentPurchaseTime+intExistingPurchasedTime;
			int intValidUntilMinutesPlus1 = intValidUntilMinutes + 1;
			int intValidUntilMinutesMinus1 = intValidUntilMinutes - 1;
			String strFreeParkingEndTime = objDictionary.get("strFreeParkingEndTime");
			String strActualValidUntil = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Valid until", 1, "strActualValueUntil");
			String strValidUntilTime = "Valid until "+AddTimeToExistingTime(strFreeParkingEndTime, Integer.toString(intValidUntilMinutes),"h:mm").replace(":00","");
			String strValidUntilTimePlus1 = "Valid until "+AddTimeToExistingTime(strFreeParkingEndTime, Integer.toString(intValidUntilMinutesPlus1),"h:mm").replace(":00","");
			String strValidUntilTimeMinus1 = "Valid until "+AddTimeToExistingTime(strFreeParkingEndTime, Integer.toString(intValidUntilMinutesMinus1),"h:mm").replace(":00","");
			if(strActualValidUntil.contains(strValidUntilTime))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTime + ")");}
			else if(strActualValidUntil.contains(strValidUntilTimePlus1))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTimePlus1 + ")");}
			else if(strActualValidUntil.contains(strValidUntilTimeMinus1))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTimeMinus1 + ")");}
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Valid until) with index (1) did not equal (" + strValidUntilTime + ") - actual value (" + strActualValidUntil + ")");}
		}
		else
		{
			int intValidUntilMinutes = intCurrentPurchaseTime+intExistingPurchasedTime;
			int intValidUntilMinutesMinusOne = intCurrentPurchaseTime-1+intExistingPurchasedTime;
	    	int intValidUntilMinutesPlusOne = intCurrentPurchaseTime+1+intExistingPurchasedTime;
	    	int intValidUntilMinutesPlusTwo = intCurrentPurchaseTime+2+intExistingPurchasedTime;
	    	//Validate Valid until Time
	    	String strActualValidUntil = clsCommonMobile.StoreText(objDictionary, androiddriver, "Meter Payment", "Valid until", 1, "strActualValueUntil");
			String strValidUntilTime = "Valid until "+AddTimeToExistingTime(strParkingSessionsParkedAtTime, Integer.toString(intValidUntilMinutes),"h:mm a").replace(":00","");
			String strValidUntilTimeMinusOne = "Valid until "+AddTimeToExistingTime(strParkingSessionsParkedAtTime, Integer.toString(intValidUntilMinutesMinusOne),"h:mm a").replace(":00","");
			String strValidUntilTimePlusOne = "Valid until "+AddTimeToExistingTime(strParkingSessionsParkedAtTime, Integer.toString(intValidUntilMinutesPlusOne),"h:mm a").replace(":00","");
	    	String strValidUntilTimePlusTwo = "Valid until "+AddTimeToExistingTime(strParkingSessionsParkedAtTime, Integer.toString(intValidUntilMinutesPlusTwo),"h:mm a").replace(":00","");
	    	if(strActualValidUntil.equals(strValidUntilTime))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTime + ")");}
			else if(strActualValidUntil.equals(strValidUntilTimeMinusOne))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTimeMinusOne + ")");}
			else if(strActualValidUntil.equals(strValidUntilTimePlusOne))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTimePlusOne + ")");}
			else if(strActualValidUntil.equals(strValidUntilTimePlusTwo))
			{Reporter.log("The Text (Valid until) with index (1) equaled (" + strValidUntilTimePlusTwo + ")");}
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (Valid until) with index (1) did not equal (" + strValidUntilTime + ") - actual value (" + strActualValidUntil + ")");}
		}
	}
