	public String VALIDATIONS_ParkingSessions_ParkedAt(Map<String, String> objDictionary,AndroidDriver androiddriver)
	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Validate Parked at Time
		String strParkingSessionsParkedAtTime = objDictionary.get("strParkingSessionsParkedAtTime");
		String strParkingSessionsParkedAtTimeMinusOne = objDictionary.get("strParkingSessionsParkedAtTimeMinusOne");
		String strParkingSessionsParkedAtTimeMinusTwo = objDictionary.get("strParkingSessionsParkedAtTimeMinusTwo");
		String strParkingSessionsParkedAtTimePlusOne = objDictionary.get("strParkingSessionsParkedAtTimePlusOne");
		String strActualParkingSessionsParkedAtTime = clsCommonMobile.StoreText(objDictionary, androiddriver, "Parking Sessions", "Parked at", 1, "strActualParkingSessionsParkedAtTime");
		//There is a bug that displays the date in the wrong format between 7 and 8 am.
		SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        // Get the current date
        Date currentDate = new Date();
        // Format the current date
        String formattedDate = sdf.format(currentDate);
        // Print the formatted date
        System.out.println(formattedDate);
        strActualParkingSessionsParkedAtTime = strActualParkingSessionsParkedAtTime.replace("Parked at : "+formattedDate,"Today");
        if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTime))
		{
			Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+ strParkingSessionsParkedAtTime+")-Actual");
			return strParkingSessionsParkedAtTime;
		}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimeMinusTwo))
		{
			Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimeMinusTwo+")-Plus2");
			return strParkingSessionsParkedAtTimeMinusTwo;
		}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimeMinusOne))
		{
			Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimeMinusOne+")-Minus1");
			return strParkingSessionsParkedAtTimeMinusOne;
		}
		else if(strActualParkingSessionsParkedAtTime.equals("Parked "+strParkingSessionsParkedAtTimePlusOne))
		{
			Reporter.log("The Text (Parked at) with index (1) equaled (Parked "+strParkingSessionsParkedAtTimePlusOne+")Plus1");
			return strParkingSessionsParkedAtTimePlusOne;
		}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (Parked at) with index (1) did not equal (Parked " + strParkingSessionsParkedAtTime + ") - actual value (" + strActualParkingSessionsParkedAtTime + ")");}
		return "";
	}
