	public void SENTRYMOBILE_ValidateConciergeAlertBalanceIsLow(Map<String, String> objDictionary, AndroidDriver androiddriver, String strRole)
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strAppWarningStatus = clsHttpConnections.GET_GetSubscriptionPreference(objDictionary, "Warnings", "app", strRole);
		String strCurrentAccountBalance = "";try{strCurrentAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary,strRole);}catch (Exception e) {}
		//Your MPS Concierge balance is low
		if(strAppWarningStatus.equals("true"))
		{
			//Get Concierge Min. Amount Before Warning
			String strMinAccountBalanceBeforeWarning =  clsHttpConnections.GET_GetConciergeAdminSetting(objDictionary, "min_amount_before_warning");
			if(Integer.parseInt(strCurrentAccountBalance) < Integer.parseInt(strMinAccountBalanceBeforeWarning))
			{
				clsCommonMobile.GlobalWait(objDictionary,androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Warning Dialog Message", 5);
				clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Warning Dialog Message", 1, "Value", "Your MPS Concierge balance is low");
	   			//Validate Push Notification
				clsCommonMobile.ValidatePushNotificaton(objDictionary, androiddriver, "Your MPS Concierge balance is low");
				clsCommonMobile.ClickLink(objDictionary, androiddriver, "Parking Sessions", "OK", 1);
			}
		}
	}
