	public AndroidDriver SetSmsDriver_AI(Map<String, String> objDictionary, String strGPSEnabled) throws MalformedURLException, InterruptedException {
	    String port = objDictionary.get("strDeviceAppiumPort");

	    // 1. STOP ANY EXISTING APPIUM SERVER
	    stopServer(objDictionary);                    // ← THIS IS YOUR ORIGINAL stopServer()
	    Thread.sleep(3000);

	    // 2. START APPIUM WITH THE REQUIRED FLAG FOR SMS
	    CommandLine command = new CommandLine("appium");
	    command.addArgument("--port", false);
	    command.addArgument(port);
	    command.addArgument("--address", false);
	    command.addArgument("127.0.0.1");
	    command.addArgument("--session-override", true);
	    command.addArgument("--allow-insecure=uiautomator2:adb_shell", false);  // ← THIS IS CRITICAL

	    DefaultExecuteResultHandler handler = new DefaultExecuteResultHandler();
	    DefaultExecutor executor = new DefaultExecutor();

	    try {
	        Reporter.log("Starting Appium server on port " + port + " with adb_shell enabled (for SMS test only)...");
	        executor.execute(command, handler);       // ← THIS STARTS APPIUM
	        Thread.sleep(18000);  // Wait ~18 seconds for Appium 2.x to be fully ready
	        Reporter.log("Appium server started and ready on port " + port);
	    } catch (Exception e) {
	        Assert.fail("Failed to start Appium for SMS test: " + e.getMessage());
	    }

	    // 3. NOW CREATE THE DRIVER
	    UiAutomator2Options options = new UiAutomator2Options();
	    options.setPlatformName("Android");
	    options.setAutomationName("UiAutomator2");
	    options.setNewCommandTimeout(Duration.ofMinutes(6));
	    options.setCapability("appium:autoGrantPermissions", true);

	    // Chromedriver fix — never fails again
	    options.setChromedriverUseSystemExecutable(true);
	    options.setChromedriverDisableBuildCheck(true);
	    options.ensureWebviewsHavePages();

	    String udid = objDictionary.getOrDefault("strAndroidUdid", "");
	    if (udid.isEmpty()) {
	        options.setAvd(objDictionary.get("strAVDName")).setDeviceName(objDictionary.get("strAVDName"));
	    } else {
	        options.setUdid(udid).setDeviceName("Android Device");
	    }

	    options.setNoReset(true);
	    options.setFullReset(false);

	    AndroidDriver driver = new AndroidDriver(new URL("http://127.0.0.1:" + port), options);
	    Reporter.log("SMS Driver created successfully");
	    
//	    try {
//	        driver.executeScript("mobile: shell", Map.of(
//	            "command", "pm grant com.google.android.apps.messaging android.permission.READ_SMS"
//	        ));
//	        Thread.sleep(2000);
//	    } catch (Exception ignored) {}

//	    Reporter.log("SMS permissions granted — no more Welcome screen or MPS prompt");

	    return driver;
	}
	
	public void sendSms(AndroidDriver driver, String phoneNumber, String message) throws InterruptedException {
	    // 1. Send the SMS — your original perfect method
	    String openCmd = String.format(
	        "am start -a android.intent.action.SENDTO -d sms:%s --es sms_body \"%s\" --ez exit_on_sent true",
	        phoneNumber, message.replace("\"", "\\\"")
	    );
	    driver.executeScript("mobile: shell", Map.of("command", openCmd));
	    Thread.sleep(3000);
	    driver.executeScript("mobile: shell", Map.of("command", "input tap 1000 2150"));  // SEND
	    Thread.sleep(2000);

	    // 2. REOPEN THE CONVERSATION SO WE CAN SEE THE REPLY
//	    driver.executeScript("mobile: shell", Map.of(
//	        "command", "am start -n com.google.android.apps.messaging/.ui.ConversationListActivity"
//	    ));
//	    Thread.sleep(3000);

	    // 3. Tap on the latest conversation (yours)
//	    driver.findElement(By.xpath("//android.widget.TextView[@text='" + phoneNumber + "']")).click();
//	    Thread.sleep(4000);
	}

	public String waitForSmsContaining(AndroidDriver driver, String text, int timeoutSec) throws InterruptedException {
	    text = text.toLowerCase();
	    long deadline = System.currentTimeMillis() + timeoutSec * 1000L;

	    while (System.currentTimeMillis() < deadline) {
	        try {
	            List<WebElement> messages = driver.findElements(
	                By.id("com.google.android.apps.messaging:id/message_text")
	            );

	            if (!messages.isEmpty()) {
	                String lastMessage = messages.get(messages.size() - 1).getText().toLowerCase();
	                if (lastMessage.contains(text)) {
	                    Reporter.log("REPLY RECEIVED: " + messages.get(messages.size() - 1).getText());
	                    return messages.get(messages.size() - 1).getText();
	                }
	            }
	        } catch (Exception ignored) {}

	        Thread.sleep(2000);
	    }
	    throw new RuntimeException("No reply with '" + text + "' after " + timeoutSec + "s");
	}
	
	public String getLatestSMSContaining(AndroidDriver driver, String text) {
	    // Simple poll for message (or use content provider query if needed)
	    for (int i = 0; i < 15; i++) {
	        try {
	            String msg = driver.findElement(By.xpath(
	                "(//android.widget.TextView[@resource-id='com.google.android.apps.messaging:id/message_text'])[1]"
	            )).getText();
	            if (msg.contains(text)) return msg;
	        } catch (Exception ignored) {}
	        try { Thread.sleep(2000); } catch (Exception ignored) {}
	    }
	    throw new RuntimeException("SMS with '" + text + "' not received");
	}
	
