	public void SENTRYMOBILE_ValidateConciergeTextBalanceIsLow(Map<String, String> objDictionary, AndroidDriver androiddriver,String strRole, SMS clsSMS,int intMeterIncrementTimeMins)
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Validate Text Message:  MPS Concierge balance is low
		String strTextNotificationStatus = clsHttpConnections.GET_GetSubscriptionPreference(objDictionary, "Warnings", "text", strRole);
		if(strTextNotificationStatus.equals("true"))
		{
			//Get Current Balance
			String strCurrentAccountBalance = "";
			try{strCurrentAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary,strRole);}catch (Exception e) {}
			//Get Concierge Min. Amount Before Warning
			String strMinAccountBalanceBeforeWarning =  clsHttpConnections.GET_GetConciergeAdminSetting(objDictionary, "min_amount_before_warning");
			if(Integer.parseInt(strCurrentAccountBalance) < Integer.parseInt(strMinAccountBalanceBeforeWarning))
			{
	   			String mySMS = clsSMS.ReturnSMS(objDictionary);
	   			System.out.println(mySMS);
	   			if(mySMS.contains("Your MPS Concierge balance is low"))
	   			{Reporter.log("<font color='blue'>Your MPS Concierge balance is low</font>");}
	   			else
				{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,null,"The text message (Your MPS Concierge balance is low) was not received");}
	   			clsCommonMobile.ClickButton(objDictionary, androiddriver, "Account Details", "Close-SMS", 1);
			}
		}
	}
