	public void SENTRYMOBILE_ValidateConciergeTextEnjoyConcierge(Map<String, String> objDictionary, AndroidDriver androiddriver,String strRole, String strLicensePlateNumber)
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Validate Text Message:  MPS Concierge balance is low
		String strInformationTextSubscription = clsHttpConnections.GET_GetSubscriptionPreference(objDictionary, "Session","text",strRole);
		if(strInformationTextSubscription.equals("true"))
		{
			androiddriver.openNotifications();
			try {Thread.sleep(2000);}catch (Exception e) {}
			List<WebElement> allNotifications = androiddriver.findElements(By.id("android:id/message_text"));
			System.out.println(allNotifications.size());
			String strFullNotificationMessage = "";
			for (WebElement notification : allNotifications)
			{
				System.out.println(notification.getAttribute("text"));
				strFullNotificationMessage = strFullNotificationMessage + notification.getAttribute("text")+" ";
			}
			if(strFullNotificationMessage.equals("We hope you enjoy the convenience MPS Concierge offers. "))
			{Reporter.log("<font color='Blue'>We hope you enjoy the convenience MPS Concierge offers. </font>");}
			else
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary,null,"The text message (We hope you enjoy the convenience MPS Concierge offers.) was not received-Actual Message:"+strFullNotificationMessage);}
			//Clear Notifications
			androiddriver.findElement(By.id("com.android.systemui:id/clear_all")).click();
			androiddriver.pressKey(new KeyEvent(AndroidKey.BACK));
		}
	}
