	public void SENTRYMOBILE_EnrollInConciergeProgram_Park_ValidatePaymentsAndNotifications(Map<String, String> objDictionary, String strTestCaseName, String strRole, String strLicensePlateNumber, String strState, String strSpotNumber, String strFreeTimeFirstPayment,String strMeterIncrementTimeMins)
	{
		Meter clsMeter = new Meter();
		CommonWeb clsCommonWeb = new CommonWeb();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		HttpConnections clsHttpConnections = new HttpConnections();
		AndroidDriver androiddriver = clsCommonMobile.SENTRYMOBILE_EnrollInConcierge(objDictionary, strTestCaseName, strLicensePlateNumber, strState, strRole, "Enroll later", "Account Details","Enabled");
		String strMinutesAdvanceSubsequent = clsHttpConnections.GET_GetConciergeAdminSetting(objDictionary, "minutes_advance_subsequent");
		if(!strMinutesAdvanceSubsequent.equals("1")){clsCommonWeb.SENTRYLINK_UpdateConciergeAdminSetting(objDictionary, "25", "25", "600", "400", "1", "10");}
		//Concierge enrollment takes affect after 2nd parking session
		if(androiddriver != null)
		{
			clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null, "1","Local");
		}
		else
		{
			//Open Consumer App
			androiddriver = clsCommonMobile.SetMobileDriver(objDictionary, "SentryMobile","True",strRole);
			try {Thread.sleep(1000);}catch (Exception e) {}
			clsCommonMobile.SENTRYMOBILE_Open(objDictionary, androiddriver);
			clsCommonMobile.SENTRYMOBILE_LoginOrRegisterWithRememberMeOnEmailIdWithoutCaps(objDictionary, androiddriver, strRole);
		}
		//Add Phone Number
		clsCommonMobile.SENTRYMOBILE_ParkingSession_AddPhoneNumber(objDictionary, androiddriver,strRole);
		//Install And Configure Messager App
		SMS clsSMS = clsCommonMobile.SENTRYMOBILE_InstallAndConfigureMessengerApp(objDictionary, androiddriver, strRole);
		//Navigate to Parking Session Page
		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver,"Parking Sessions");
		//Park With License Plate Wait For Payment
		clsMeter.METER_ParkSpotWithActiveConciergeLicensePlate(objDictionary, strLicensePlateNumber);
		//Validate Concierge Purchase And Notifications
		clsCommonMobile.SENTRYMOBILE_ValidateConciergePurchaseAndNotifications(objDictionary, androiddriver, clsSMS, strRole, strLicensePlateNumber, strSpotNumber, strFreeTimeFirstPayment,  Integer.parseInt(strMeterIncrementTimeMins), "True");
		//WUMRMBANP: Wait Until Meter Reaches Minutes Before Advanced Next Payment
		String strMeterRemainingTime = clsMeter.GetMeterValidTimeRemaining(objDictionary, null, "1");
   		int intSecondsBeforeViolation = Integer.parseInt(strMeterRemainingTime);
   		int intSecondBeforeNextConciergePayment = intSecondsBeforeViolation - (Integer.parseInt(strMinutesAdvanceSubsequent) * 60);
   		//Wait Meter Time Expire
   		clsMeter.METER_MeterWaitWithMessage(objDictionary,intSecondBeforeNextConciergePayment, "Decrement to Minutes before Advanced Next Payment-Spot"+strSpotNumber);
   		Reporter.log("<font color='firebrick'>Waited ("+intSecondBeforeNextConciergePayment+") Before Next Concierge Payment</font>");
   		//VMT: Validate Meter Time
   		String strOriginalValidTimePurchase = clsMeter.GetMeterValidTimePurchased(objDictionary,null,"1","Local","");
   		clsMeter.METER_WaitForMeterPayment(objDictionary, strOriginalValidTimePurchase);
   		int intExpectedMeterTime = Integer.parseInt(strMeterIncrementTimeMins) + Integer.parseInt(strMinutesAdvanceSubsequent);
   		clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null, intExpectedMeterTime, strSpotNumber);
   		//Validate Concierge Purchase And Notifications
   		clsCommonMobile.SENTRYMOBILE_ValidateConciergePurchaseAndNotifications(objDictionary, androiddriver, clsSMS, strRole, strLicensePlateNumber, strSpotNumber, strFreeTimeFirstPayment,  Integer.parseInt(strMeterIncrementTimeMins), "False");
		//ShortSessionWaitExitSpot
      	clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null, "1","Local");
	}
	public void SENTRYMOBILE_ValidateConciergePurchaseAndNotifications(Map<String, String> objDictionary, AndroidDriver androiddriver, SMS clsSMS, String strRole, String strLicensePlateNumber, String strSpotNumber, String strFreeTimeFirstPayment,int intMeterIncrementTimeMins, String strFirstPayment)
	{
		Meter clsMeter = new Meter();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//VMT: Validate Meter Time
		clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null, intMeterIncrementTimeMins, strSpotNumber);
		//Application Message: MPS Concierge balance is low
		clsCommonMobile.SENTRYMOBILE_ValidateConciergeAlertBalanceIsLow(objDictionary, androiddriver, strRole);
		//Application Message: Concierge Purchase at meter 9000
		clsCommonMobile.SENTRYMOBILE_ValidateConciergeAlertConciergePurchase(objDictionary, androiddriver, strSpotNumber,strRole, strLicensePlateNumber);
		//Validate Text Message:  MPS Concierge balance is low
		clsCommonMobile.SENTRYMOBILE_ValidateConciergeTextBalanceIsLow(objDictionary, androiddriver,strRole, clsSMS,intMeterIncrementTimeMins);
		//Validate Text Message:  Concierge Purchase at meter 9000
		clsCommonMobile.SENTRYMOBILE_ValidateConciergeTextConciergePurchase(objDictionary, androiddriver, strRole, strSpotNumber, strLicensePlateNumber, clsSMS);
		//VPSV: Validate Parking Session Values
		if(strFirstPayment.equals("True"))
		{SENTRYMOBILE_ParkingSession_ValidateValues_FirstPayment(objDictionary,androiddriver, strFreeTimeFirstPayment, String.valueOf(intMeterIncrementTimeMins), strLicensePlateNumber);}
		else
		{SENTRYMOBILE_ParkingSession_ValidateValues_SubsequentPayment(objDictionary,androiddriver, strFreeTimeFirstPayment, String.valueOf(intMeterIncrementTimeMins), strLicensePlateNumber);}
	}




