	public void SENTRYMOBILE_ParkingSession_ValidateValues_FirstPayment(Map<String, String> objDictionary, AndroidDriver androiddriver, String strFreeTimeFirstPayment, String strMeterIncrementTimeMins, String strLicensePlateNumber)
  	{
		CommonANDROID clsCommonMobile = new CommonANDROID();
		HttpConnections clsHttpConnections = new HttpConnections();
		//Validate Spot and License Plate
		clsCommonMobile.VALIDATIONS_ParkingSessions_SpotAndLicensePlateNumber(objDictionary, androiddriver, strLicensePlateNumber);
		//Validate Parked at Time
		clsCommonMobile.VALIDATIONS_ParkingSessions_ParkedAt(objDictionary, androiddriver);
		//ValidateParkingSessionsValidUntil
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsValidUntil(objDictionary,androiddriver,Integer.parseInt(strMeterIncrementTimeMins));
		//ValidateParkingSessionsParkingExipresIn
		clsCommonMobile.VALIDATIONS_ValidateParkingSessionsParkingExipresIn(objDictionary,androiddriver,Integer.parseInt(strMeterIncrementTimeMins));
		//Expand Receipt Section
    	String strConditional = clsCommonMobile.ConditionalStepText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Exists", "");
    	if(strConditional.equals("False"))
    	{
    		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Parking Sessions", "DropDownArrow", 1);
    	 	try {Thread.sleep(2000);}catch (Exception e) {}
    	}
    	clsCommonMobile.GlobalWait(objDictionary, androiddriver, "Parking Sessions", "{TextExists} Parking Sessions~Amount Paid", 15);
    	//Validate Receipt No
    	try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
    	String strFirstPayment = objDictionary.get("strFirstPayment");
    	String strParkingFee = "0";
    	String strTotalPurchaseAmt = "$0.25";
    	if(!strFirstPayment.equals("0"))
    	{
    		//double dblTotalFee = Double.parseDouble(strTotalFee.replace("$",""));
    		double dblConvenienceFee = Double.parseDouble(strFirstPayment)*.01;
    		double dblParkingFee = dblConvenienceFee;
    		DecimalFormat dFormat = new DecimalFormat("$0.00");
    		strParkingFee = dFormat.format(dblParkingFee);
    		Double dblTotalPurchaseAmt = Double.parseDouble(strTotalPurchaseAmt.replace("$", "")) + dblParkingFee;
    		strTotalPurchaseAmt =  dFormat.format(dblTotalPurchaseAmt)+" (Conv. fee "+strParkingFee+")";
    	}
    	clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Amount Paid", 1, "Contains", strTotalPurchaseAmt);
	    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");Date date = new Date();
		String strPurchaseAt = dateFormat.format(date);
		int intPurchaseTime = Integer.parseInt(strMeterIncrementTimeMins) + Integer.parseInt(strFreeTimeFirstPayment);
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Time purchased", 1, "Contains", intPurchaseTime+" Minutes");
		clsCommonMobile.VerificationPointText(objDictionary, androiddriver, "Parking Sessions", "Purchased At", 1, "Contains", strPurchaseAt);
  	}
