	public void SENTRYMOBILE_ParkingSession_AddPhoneNumber(Map<String, String> objDictionary, AndroidDriver androiddriver,String strRole)
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		//Enable, Add or Update Phone Number
		String strSessionTextStatus = clsHttpConnections.GET_GetSubscriptionPreference(objDictionary, "Session", "text", strRole);
		String strWarningTextStatus = clsHttpConnections.GET_GetSubscriptionPreference(objDictionary, "Warnings", "text", strRole);
		String strInformationTextStatus = clsHttpConnections.GET_GetSubscriptionPreference(objDictionary, "Information", "text", strRole);
		if(strSessionTextStatus.equals("true")||strWarningTextStatus.equals("true")||strInformationTextStatus.equals("true"))
		{
			String strSentryLinkPhone = clsHttpConnections.GET_ReturnUserPreference(objDictionary,strRole, "phone_number") ;
			String strDevicePhone = objDictionary.get("strDevicePhone");
			String strSendSMSBackup = clsHttpConnections.GET_ReturnUserPreference(objDictionary, strRole, "send_sms_as_backup_for_push_notification");
			if(!strDevicePhone.equals(strSentryLinkPhone)||strSentryLinkPhone.equals(""))
			{
				clsCommonMobile.SENTRYMOBILE_AccountDetails_AddPhoneNumber(objDictionary, androiddriver, strDevicePhone, strRole);
			}
			else if(strSendSMSBackup.equals("false"))
			{
				clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,androiddriver,"Account Details");
				clsCommonMobile.ClickButton(objDictionary, androiddriver, "Account Details", "Phone no", 1);
			}
		}
	}


