	//**********************
	//Object Wait Section
	//**********************
	public AndroidDriver DynamicObjectWait(Map<String, String> objDictionary,AndroidDriver androiddriver, String strPageName)
    {
		Meter clsMeter = new Meter();
		CommonWeb clsCommonWeb = new CommonWeb();
		String strObjectValue2 = "";
		String strTimeoutFlag = "False";
		String strVehicleParkType = objDictionary.get("strVehicleParkType");
		Timestamp currentTime = new Timestamp(System.currentTimeMillis());
        Calendar cal = Calendar.getInstance();
        cal.setTimeInMillis(currentTime.getTime());
        cal.add(Calendar.SECOND, intWaitTime);
        Timestamp endTime = new Timestamp(cal.getTime().getTime());
        //Used when Parking is Purchased-VehicleParkSpot
        String strExecutedFlag = "False";
        Calendar cal2 = Calendar.getInstance();
        cal2.setTimeInMillis(currentTime.getTime());
        cal2.add(Calendar.SECOND, 45);
        Timestamp endTime2 = new Timestamp(cal2.getTime().getTime());
        do
        {
            String[] arrWaitObjects = strWaitObjects.split("\\|");
            for (String WaitObject : arrWaitObjects)
            {
                String[] arrWaitObject = WaitObject.split("}");
                String strWaitType = arrWaitObject[0].substring(1);
                String[] arrWaitValue = arrWaitObject[1].trim().split("~");
                int intWaitValueLenght = arrWaitValue.length;
                String strWaitValue = arrWaitValue[0];
                if (intWaitValueLenght == 2) {strObjectValue2 = arrWaitValue[1];}
                strActualWaitType = strWaitType;
                strActualWaitValue = strWaitValue;
                WebElement objName = null;
                switch (strWaitType)
                {
	                case "ButtonExists":
	                	strActualWaitValue = strObjectValue2;
	                	if(strObjectValue2.contains("Where's my car?"))
	                	{
	                		//I Close
	                		NotitificationHandler(objDictionary, androiddriver);
	                	}
	            		objName = GetButtonObj(objDictionary, androiddriver, strWaitValue, strObjectValue2,1);
	            		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
	            		break;
                	case "LinkExists":
                		objName = GetLinkObj(objDictionary, androiddriver, strPageName, strWaitValue);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "PageExists":
                		objName = GetPageObj(objDictionary,androiddriver,strWaitValue);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "TextExists":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary,androiddriver,strWaitValue,strObjectValue2,1);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "TextFieldExists":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextFieldObj(objDictionary, androiddriver, strWaitValue, strObjectValue2);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30; return androiddriver;}
                		break;
                	case "ThreadStoreMeterValues":
                		String strMeterValidTimePurchased = objDictionary.get("strMeterValidTimePurchased");
                		if(strMeterValidTimePurchased == null)
                		{
                			clsMeter.StoreMaxTime_MaxRemaining_ValidTimePurchased_ValidTimeRemaining_Violation_Unlocked(objDictionary);
                		}
                		break;
                }
                currentTime = new Timestamp(System.currentTimeMillis());
                if (currentTime.getTime() > endTime.getTime())
                {
                	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"None of the expected objects (" + strWaitObjects + ") existed after (" + intWaitTime + ") seconds");
                }
            }
        }while (strTimeoutFlag == "False");
		return androiddriver;
    }
	public AndroidDriver GlobalWait(Map<String, String> objDictionary,AndroidDriver androiddriver, String strPageName, String strWaitObjects, int intWaitTime)
	{
		Meter clsMeter = new Meter();
		String strObjectValue2 = "";
		String strTimeoutFlag = "False";
        Timestamp currentTime = new Timestamp(System.currentTimeMillis());
        Calendar cal = Calendar.getInstance();
        cal.setTimeInMillis(currentTime.getTime());
        cal.add(Calendar.SECOND, intWaitTime);
        Timestamp endTime = new Timestamp(cal.getTime().getTime());
        HttpConnections clsHttpConnections = new HttpConnections();
        do
        {
            String[] arrWaitObjects = strWaitObjects.split("\\|");
            for (String WaitObject : arrWaitObjects)
            {
                String[] arrWaitObject = WaitObject.split("}");
                String strWaitType = arrWaitObject[0].substring(1);
                String[] arrWaitValue = arrWaitObject[1].trim().split("~");
                int intWaitValueLenght = arrWaitValue.length;
                String strWaitValue = arrWaitValue[0];
                if (intWaitValueLenght == 2) {strObjectValue2 = arrWaitValue[1];}
                strActualWaitType = strWaitType;
                strActualWaitValue = strWaitValue;
                WebElement objName = null;
                switch (strWaitType)
                {
	                case "ButtonExists":
	                	strActualWaitValue = strObjectValue2;
	                	objName = GetButtonObj(objDictionary, androiddriver, strWaitValue, strObjectValue2,1);
	            		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
	            		break;
                	case "LinkExists":
                		objName = GetLinkObj(objDictionary, androiddriver, strPageName, strWaitValue);
                		if(objName != null)
                		{strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "PageExists":
                		objName = GetPageObj(objDictionary,androiddriver,strWaitValue);
                		if(objName != null)
                		{strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "TextExists":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary,androiddriver,strPageName,strObjectValue2,1);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "TextFieldExists":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextFieldObj(objDictionary, androiddriver, strWaitValue, strObjectValue2);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30; return androiddriver;}
                		break;
                	case "GoogleMapTagExists":
                		try{objName = androiddriver.findElement(By.xpath("//*[contains(@content-desc,'"+strWaitValue+"')]"));}catch(Exception e) {objName = null;}
                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return androiddriver;}
                		break;
                	case "WaitUntilMeterVariableBegunEqualTrue":
                		String strMeterValidTimePurchased = objDictionary.get("strMeterValidTimePurchased");
                		if(strMeterValidTimePurchased == null)
                		{
                			clsMeter.StoreMaxTime_MaxRemaining_ValidTimePurchased_ValidTimeRemaining_Violation_Unlocked(objDictionary);
                		}
                		break;
                	case "WaitUntilJsonParkingSessionInformationNotBlank":
                		String IsBlank = clsHttpConnections.CheckJsonParkingSessionInformationIsBlank(objDictionary);
                		if(IsBlank.equals("False")) {strWaitObjects = "";intWaitTime = 30; return androiddriver;}
                		break;

                }
                currentTime = new Timestamp(System.currentTimeMillis());
                if (currentTime.getTime() > endTime.getTime())
                {
                 	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"None of the expected objects (" + strWaitObjects + ") existed after (" + intWaitTime + ") seconds");
                }
            }
        }while (strTimeoutFlag == "False");
        return androiddriver;
	}

