	public void VerificationPointListbox(Map<String, String> objDictionary,AndroidDriver androiddriver, String strPageName, String strListboxName, int intListboxIndex, String strValidationType, String strListboxValue)
    {
		WebElement objListbox = GetListboxObj(objDictionary,androiddriver, strPageName, strListboxName);
		String strActualItemOrder = "";
		List<WebElement> options = null;
		if (objListbox != null)
	    {
			switch (strValidationType)
            {
            	case "Value":
            		String strListboxSelectedOption = new Select(objListbox).getFirstSelectedOption().getText();
            		if ((strListboxSelectedOption.trim()).equals(strListboxValue.trim()))
            		{Reporter.log("The Listbox (" + strListboxName + ") with index (" + intListboxIndex + ") equaled (" + strListboxValue + ")"+"");}
            		else
            		{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The listbox (" + strListboxName + ") with index (" + intListboxIndex + ") did not equal (" + strListboxValue + ") - actual value (" + strListboxSelectedOption + ")");}
                    return;
            	 case "Item Count":
            		 int intListboxNumberOfItems = new Select(objListbox).getOptions().size();
            		 if(intListboxNumberOfItems == Integer.parseInt(strListboxValue))
                     {Reporter.log("The listbox (" + strListboxName + ") with index (" + intListboxIndex + ") contained (" + strListboxValue + ") items"+"");}
                     else
                     {UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The listbox (" + strListboxName + ") with index (" + intListboxIndex + ") did not contained (" + strListboxValue + ") items - actual number of items (" + intListboxNumberOfItems + ")");}
                     return;
            	case "Item Order":
                    options = objListbox.findElements(By.tagName("option"));
                    for (WebElement option : options){strActualItemOrder = strActualItemOrder + "|" + option.getText();}
                    strActualItemOrder = strActualItemOrder.substring(1);
                    if (strActualItemOrder.equals(strListboxValue))
                    {Reporter.log("The item order for the Listbox (" + strListboxName + ") with index (" + intListboxIndex + ") were displayed in the expected order (" + strListboxValue + ")"+"");}
                    else
                    {
                    	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The item order for the Listbox (" + strListboxName + ") with index (" + intListboxIndex + ") were not displayed in the expected order (" + strListboxValue + ") - actual order (" + strActualItemOrder + ")");
                    }
                    return;
            	 case "Items Do Not Exist":
                     String[] strUnexpectedItem = strListboxValue.split("\\|");
                     options = objListbox.findElements(By.tagName("option"));
                     for (WebElement option : options){strActualItemOrder = strActualItemOrder + "|" + option.getText();}
                     for (String item : strUnexpectedItem)
                     {
                    	 if (strActualItemOrder.substring(1).contains(item))
                    	 {
                    		 UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The item (" + item + ") existed in the (" + strListboxName + ") listbox with index (" + intListboxIndex + ")");
                    	 }
                     }
                     Reporter.log("All of the unexpected items (" + strListboxValue + ") did not exist in the (" + strListboxName + ") listbox with index (" + intListboxIndex + ")");
                     return;
            	 case "Items Exist":
                     String[] strExpectedItem = strListboxValue.split("\\|");
                     options = objListbox.findElements(By.tagName("option"));
                     for (WebElement option : options){strActualItemOrder = strActualItemOrder + "|" + option.getText();}
                     for (String item : strExpectedItem)
                     {
                    	 if (!strActualItemOrder.substring(1).contains(item))
                    	 {
                    		 UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The item (" + item + ") did not exist in the (" + strListboxName + ") listbox with index (" + intListboxIndex + ")");
                    	 }
                     }
                     Reporter.log("All of the expected items (" + strListboxValue + ") existed in the (" + strListboxName + ") listbox with index (" + intListboxIndex + ")");
                     return;
                case "Disabled":
	                if (!objListbox.isEnabled()){Reporter.log("The Listbox (" + strListboxName + ") at index (" + intListboxIndex + ") was disabled");}
	                else
	                {
	                	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Listbox  (" + strListboxName + ") at index (" + intListboxIndex + ") was not disabled");
               		}
	                return;
	            case "Does Not Exist":
	            	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Listbox  (" + strListboxName + ") at index (" + intListboxIndex + ") existed");
           		 	return;
	            case "Enabled":
	            	if (objListbox.isEnabled()){Reporter.log("The Listbox (" + strListboxName + ") at index (" + intListboxIndex + ") was enabled");}
	            	else
	            	{
	            		UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Listbox (" + strListboxName + ") at index (" + intListboxIndex + ") was not enabled");
	            	}
	                return;
	            case "Exists":
	            	Reporter.log("The Listbox (" + strListboxName + ") at index (" + intListboxIndex + ") existed");
	                return;
	            default:
	            	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Listbox validation type (" + strValidationType + ") hasn't been coded yet - VerificationPointCheckbox");
           		 	return;
	        }
		}
	    else
	    {
	    	switch (strValidationType)
            {
                case "Does Not Exist":
                	Reporter.log("The Listbox  (" + strListboxName + ") at index (" + intListboxIndex + ") did not exist"+"");
	                return;
                case "Exists":
                	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Listbox (" + strListboxName + ") at index (" + intListboxIndex + ") did not exist");
           		 	return;
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Listbox (" + strListboxName + ") at index (" + intListboxIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
           		 	return;
            }
	    }
    }
