    public void TakeAndroidScreenShot(AndroidDriver androiddriver,Map<String, String> objDictionary,String strScreenShotName)
   	{
    	Meter clsMeter = new Meter();
    	clsMeter.METER_SetMeterEndTime(objDictionary);
    	String strAutomationUser = System.getProperty("user.name");
    	File file = null;
    	String strImageURL = "";
    	if(androiddriver != null)
    	{
    		String strDeviceName = (String)androiddriver.getCapabilities().getCapability("deviceName");
			try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s "+strDeviceName+" shell input input tap 763 1701");}
			catch (Exception e)
			{System.out.print("Unable to Swipe to activate screen for screenshot");}
			try
			{
				File screenshot = ((TakesScreenshot) androiddriver).getScreenshotAs(OutputType.FILE);
		   		File directory = new File(".");
		   		String strPath = "";
		   		if(strScreenShotName.equals("")){strPath = directory.getCanonicalPath() +"/ScreenShots/Error.png";}
		   		else{strPath = directory.getCanonicalPath() +"/ScreenShots/"+strScreenShotName+".png";}
		   		file = new File(strPath);
		   		FileUtils.copyFile(screenshot, file);
                strImageURL = ImgurClient.getInstance().UploadImage(file, "Android Screenshot " + Instant.now());
		   		if (strImageURL != null)
				{
					Reporter.log("<a href=" + strImageURL + "/>Android Screen Shot</a>");
					Reporter.log("<img src=\"" + strImageURL + "\" alt=\"\"/><br />");
				}
		   		else
		   		{
		   			Reporter.log("<a href=" + strPath + "/>Android Screen Shot</a>");
					Reporter.log("<img src=\"" + strPath + "\" alt=\"\"/><br />");
		   		}
		   	}catch (Exception e)
			{System.out.print("Error taking mobile screen shot");}
		}
    	else
    	{Reporter.log("Unable to take Mobile Screen Shot Android Driver was Null");}
   	}

    public void RenameScreenShot(ITestResult testResult, ITestNGMethod testMethod, ITestContext context) throws Exception
	{
    	String strUserDir = System.getProperty("user.dir");
    	String strPackageWithTestCaseName = testResult.getTestClass().getName();
		String strMethodName = testResult.getName();
		String strXmlBrowserName = testResult.getTestClass().getXmlTest().getParameter("strBrowser");
		String strXmlTestName = testResult.getTestClass().getXmlTest().getName();
		String strScreenShotName = "";
		if(strXmlBrowserName == null)
		{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName;}
		else
		{
			if(strXmlTestName != null)
			{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName+"."+strXmlTestName+"."+strXmlBrowserName;}
			else
			{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName+"."+strXmlBrowserName;}
		}
		try
		{
	    	File oldName = new File(strUserDir+"/ScreenShots/Error.png");
	        File newName = new File(strUserDir+"/ScreenShots/"+strScreenShotName+".png");
	        if(oldName.renameTo(newName))
	        {System.out.println("The File Error.png was renamed to "+strScreenShotName+".png");}
	        else {System.out.println("Error renaming File Error.png to "+strScreenShotName+".png");}
		}
		catch (Exception e)
		{
			System.out.println("MIH");
		}
	}
